const records=[],topics={arithmetic:'Percentages, ratios and growth',decisions:'Expected value, Kelly and decisions',applications:'Trading, betting and poker'};
function r(band,subject,key,concept,t,p,formula='',checks=[]){records.push({key:'prac-'+key,band,subject,topic:topics[subject],concept,meaning:t[0],why:t[1],rule:t[2],intuition:t[3],example:p[0],error:p[1],compare:p[2],validate:p[3],apply:p[4],extend:p[5],formula,prerequisites:[],sourceIds:subject==='arithmetic'?['q-openstax-econ']:subject==='decisions'?['q-kelly','q-openstax-econ']:['q-cme-risk','q-poker','q-betfair','q-bis','q-cme-performance'],checks:checks.map(([expression,value,tolerance])=>({expression,value,...(tolerance?{tolerance}:{})}))})}
// Absolute fundamentals.
r(1,'arithmetic','percent','Percent',[
'Percent means out of 100. 20% means 20 out of 100.','It makes groups of different sizes easier to compare.','Percent = part ÷ whole × 100. The whole is the group being counted.','Picture 100 squares: colouring 25 colours 25% of them.'
],[['30 of 100 visitors buy. What percent buy?','30 ÷ 100 × 100 = 30%.'],['Someone says 20% means 20 people, whatever the group size. What is wrong?','The number depends on the group: 20% of 100 is 20; 20% of 1,000 is 200.'],['Is 50% a half or a quarter?','A half. 50/100 = 1/2.'],['Before quoting a percentage, what number must you identify?','The whole, or denominator. 10 buyers out of 20 and out of 200 mean 50% and 5%.'],['5 of 20 customers cancel. What is the cancellation rate?','5 ÷ 20 × 100 = 25%.'],['Shop A has 10 buyers from 100 visits; B has 30 from 600. Which has a higher conversion rate?','A: 10% versus B: 5%. A has twice the rate despite fewer buyers.']],'percent = part/whole × 100',[['5/20*100',25]]);
r(1,'arithmetic','percent-of','A percentage of an amount',['A share of an amount, measured in hundredths.','It turns a risk percentage or discount into money.','Amount × percentage ÷ 100 gives the share.','10% is one of ten equal slices; 5% is half that slice.'],[['What is 10% of €200?','€200 × 0.10 = €20.'],['Is 5% of €100 the same money as 5% of €1,000?','No: €5 versus €50. Same share, different base.'],['What are 1% and 5% of €400?','€4 and €20. Multiply the 1% amount by five.'],['When calculating a stake percentage, what is the base?','The bankroll available under that rule, not the possible prize.'],['An app earns €800 and pays a 25% platform fee. How much is the fee?','€800 × 0.25 = €200.'],['A €300 item is discounted 20%. What do you pay?','Discount €60; pay €240 = €300 × 0.80.']],'share = base × p',[['300*0.8',240]]);
r(1,'arithmetic','percentage-points','Percentage points',['The direct difference between two percentage rates.','It prevents confusing a change in a rate with relative growth.','New rate minus old rate gives percentage points. Relative change divides that difference by the old rate.','Going from 10% to 15% adds five points to a 100-point scale.'],[['A rate rises from 10% to 15%. How many percentage points?','15 − 10 = 5 percentage points.'],['Is 10% to 15% a 5% relative rise?','No. It is 5 percentage points and 50% relative growth: 5 ÷ 10.'],['A rate falls from 8% to 6%. Give both changes.','−2 percentage points; −25% relative, since −2 ÷ 8 = −0.25.'],['What must a headline saying “up 5%” clarify?','Whether it means 5 percentage points or a 5% relative rise.'],['Conversion rises from 2% to 3%. How many extra buyers per 1,000 visits?','10 extra: 30 instead of 20. This is +1 percentage point and +50% relative.'],['Two treatments lower risk 20%→10% and 2%→1%. Same absolute benefit?','No. Both halve risk, but reductions are 10 and 1 percentage points.']],'pp change = new% − old%',[['(3-2)/2*100',50]]);
r(1,'arithmetic','percent-change','Percentage change',['The change compared with the starting amount.','It compares returns, prices and revenue on a common scale.','(New − old) ÷ old × 100. The starting amount must be nonzero.','An extra €10 is large beside €20 and small beside €1,000.'],[['Price goes €100→€120. What is the return?','(120 − 100) ÷ 100 × 100 = +20%.'],['Why is dividing the €20 gain by the ending €120 wrong for the return?','The return measures growth from the €100 start, so the denominator is €100.'],['Revenue goes €200→€150. What is the change?','−€50, or −25%.'],['Can ordinary percentage growth be calculated from zero revenue?','No: division by zero is undefined. Report the absolute change.'],['Customers grow 50→60. What is the growth rate?','10 ÷ 50 = 20%.'],['€100 falls to €80, then recovers to €100. Are both moves 20%?','No. The fall is 20% of €100; the recovery is 25% of €80.']],'return = (new − old)/old',[['(100-80)/80*100',25]]);
r(1,'arithmetic','ratio','Ratio',['A comparison by division, such as two wins for every loss.','It connects quantities, odds and risk/reward.','A:B means A units for B units. Divide both by the same nonzero number to simplify.','Six red balls and three blue balls simplify to two red for each blue.'],[['Simplify a 6:3 ratio.','2:1, dividing both numbers by three.'],['Does a wins:losses ratio of 2:1 mean a 50% win rate?','No. Two wins among three outcomes means 2/3 ≈ 66.67%.'],['What win fraction corresponds to wins:losses = 3:2?','3/(3+2) = 60%.'],['When reading “3:1 odds”, what must be clear?','Which quantity is first: payout, risk, wins or losses. Conventions differ.'],['A recipe uses water:concentrate = 4:1. What fraction is concentrate?','1/(4+1) = 20%.'],['A trade risks €10 to gain €30. What is reward:risk, and the break-even win rate before costs?','3:1; €10/(€30+€10) = 25%.']],'fraction A = A/(A+B)',[['10/(30+10)*100',25]]);
r(1,'decisions','ev','Expected value',['The probability-weighted average result across many similar decisions.','It compares uncertain choices using both their chances and payoffs.','Multiply each outcome by its probability, then add. Use negative numbers for losses.','Imagine repeating the same chance game many times; EV is the average, not the next result.'],[['A bet wins €20 with 60% chance and loses €20 with 40%. What is EV?','0.60 × €20 − 0.40 × €20 = +€4 per bet.'],['A bet has EV +€4. Must the next bet win €4?','No. This bet pays +€20 or −€20. €4 is the long-run expected average.'],['At 50% chance with +€20/−€20, what is EV?','€0: the positive and negative weighted amounts cancel.'],['What two inputs does a reliable EV calculation need?','Reasonable outcome probabilities and complete net payoffs, including costs.'],['A project has 50% chance of €100 profit and 50% chance of €20 loss. Find EV.','0.5 × €100 − 0.5 × €20 = +€40.'],['Would a 90% win rate automatically mean positive EV?','No. Winning €1 nine times and losing €20 once averages −€1.10 per attempt.']],'EV = Σ probability × net outcome',[['0.6*20-0.4*20',4],['0.9*1-0.1*20',-1.1]]);
r(1,'decisions','net-payoffs','Net payoff',['Money gained or lost after subtracting the cost of taking a choice.','It stops stake returns or revenue from being mistaken for profit.','Net payoff = money received − money paid.','Getting €120 back after paying €100 adds €20 to your wallet.'],[['You stake €10 and receive €25 including your stake. What is profit?','€25 − €10 = €15.'],['Someone puts the full €25 payout into an EV profit calculation. What is wrong?','They counted the returned €10 stake as profit. The winning net payoff is €15.'],['If a €10 stake loses entirely, what is the net payoff?','−€10.'],['Should a non-refundable fee enter the payoff?','Yes. Subtract it in every outcome where it is paid.'],['A raffle costs €2; 10% chance of a €10 payout, otherwise zero. Find net EV.','0.10 × €10 − €2 = −€1. Equivalently 0.1 × €8 + 0.9 × (−€2).'],['A free trial generates €6 expected revenue but costs €4 service and €3 marketing. Worth it by EV alone?','Net EV = €6 − €4 − €3 = −€1. Revenue alone was misleading.']],'net = receipt − cost',[['0.1*10-2',-1]]);
r(1,'decisions','positive-ev','Positive expected value',['An expected average net gain above zero under the model.','It separates a profitable price from a likely winner.','Compare EV with zero and with the best alternative, then assess risk and uncertain inputs.','A tilted coin can still lose; the tilt describes repeated averages.'],[['A game has EV −€2. Is it positive, negative or neutral?','Negative expected value.'],['“The favorite usually wins, so any price is good.” What is wrong?','The payout may be too small for the risk. Winning often can still lose money on average.'],['Which has larger EV: +€3 or +€5 per try?','+€5, though risk, time and capital needs can still change the choice.'],['Why check fees before declaring an edge?','A €1 gross edge with €2 costs becomes −€1 net EV.'],['Win €5 with 80% chance; lose €30 with 20%. Find EV.','0.8 × €5 − 0.2 × €30 = −€2.'],['A model estimates +€1 EV but its input error could change EV by €3. Is the sign secure?','No. The possible input error exceeds the estimated edge.']],'positive edge means net EV > 0',[['0.8*5-0.2*30',-2]]);
r(1,'decisions','outcome-vs-decision','Decision quality versus outcome',['A good decision uses sound information; its single result can still be bad.','It helps avoid learning the wrong lesson from luck.','Judge the information, price and method available before the outcome.','Taking an umbrella for an 80% rain forecast can be sensible even on a dry day.'],[['A fair die pays €10 on a six and costs €1 otherwise. It loses once. Was that loss proof of a bad choice?','No. EV = (1/6)×€10 − (5/6)×€1 ≈ +€0.83 before other costs.'],['“I won, therefore my probability estimate was right.” Why is this wrong?','Many different probabilities can produce one win. A single result does not validate the estimate.'],['Can a negative-EV choice win?','Yes. Negative EV describes its average, not every outcome.'],['How should forecast quality be judged?','Across many recorded predictions, including losses, with calibration and comparable conditions.'],['A 70% forecast loses. Is the forecast necessarily wrong?','No. A 30% losing chance was part of that forecast.'],['A strategy has ten wins, but you only saved winners. Can you estimate its EV?','No. Missing losses distort both the win rate and the average payoff.']],'EV ≠ realized result',[['10/6-5/6',5/6]]);
r(1,'decisions','opportunity-cost','Opportunity cost',['The value of the best alternative you give up.','It includes time and capital when comparing useful opportunities.','Compare a choice with the best feasible alternative, not just doing nothing.','An hour spent on one app cannot be spent on your next-best app.'],[['A task pays €50 but prevents another feasible €40 task. What is the extra payoff?','€10 above the alternative, before other costs.'],['Is the €40 forgone task an extra cash bill?','No. It is a lost alternative benefit, not necessarily money paid out.'],['What differs between accounting profit and economic profit?','Economic profit also subtracts relevant opportunity costs.'],['Which alternative should be used as the comparison?','The best feasible one, not an imaginary offer you cannot take.'],['An investment earns €100 while an equally risky feasible alternative earns €120. What is the shortfall?','€20; the first earns 16.67% less than €120.'],['Should time spent estimating a tiny edge be counted?','Yes. Compare its expected extra benefit with what that time could earn or improve elsewhere.']],'incremental value = choice − best alternative',[['(120-100)/120*100',100/6]]);
r(1,'applications','risk-reward','Risk/reward and win rate',['Profitability depends on both outcome size and winning chance.','It evaluates a trading setup beyond its win-rate headline.','Using gross payoffs: EV = p × average win − (1−p) × average loss − costs. Using net payoffs: do not subtract the same costs again.','A small bucket of wins can be emptied by one large loss.'],[['Win €30 or lose €10, with 40% win chance. Find EV before costs.','0.4 × €30 − 0.6 × €10 = +€6.'],['Does a planned 3:1 target/stop guarantee a 3:1 realized ratio?','No. Fills, early exits, gaps and fees can change the realized payoffs.'],['Win €5 or lose €20 at 70% win chance. Profitable before costs?','No. EV = €3.50 − €6 = −€2.50.'],['Which payoffs belong in an evaluated trading strategy?','Use actual filled wins and losses on a consistent gross or net basis. If already net of costs, do not subtract those costs again.'],['A 3:1 reward:risk strategy has no fees. What win rate breaks even?','1/(3+1) = 25%.'],['If a +€6 gross EV trade costs €7 in spread and fees, what is net EV?','−€1. The cost is larger than the gross edge.']],'p_break-even = loss/(win+loss)',[['0.4*30-0.6*10',6],['0.7*5-0.3*20',-2.5]]);
r(1,'applications','decimal-odds','Decimal odds and implied probability',['Decimal odds give total payout per unit staked, including the stake.','They turn a betting price into a break-even winning chance.','Implied probability = 1 ÷ decimal odds, before commission and other costs.','Odds 2.00 return two euros for every euro staked on a win.'],[['What probability is implied by decimal odds 4.00?','1/4 = 25%.'],['Does odds 4.00 prove the true chance is 25%?','No. It is the price-implied break-even chance, not verified truth.'],['At odds 2.00, a €10 winning stake returns and profits how much?','Return €20; profit €10.'],['When comparing a model probability with odds, what costs matter?','Commission, fees, taxes where applicable, and any payout restrictions.'],['Estimated chance 60%, odds 2.00, €10 stake. What is EV?','0.6 × €10 − 0.4 × €10 = +€2, assuming the estimate is sound and no costs.'],['Odds 1.25 imply what chance, and what profit on a €20 winning stake?','80% chance; payout €25 and profit €5.']],'p_implied = 1/D',[['1/4*100',25],['20*(1.25-1)',5]]);
r(1,'applications','pot-odds','Poker calling price',['The call cost as a share of the final pot after your call.','It gives the minimum equity for a simple all-in call with no future costs or rake.','Required equity = call ÷ (pot before your call + call).','Paying €20 to compete for a final €100 pot needs one fifth of it in expected share.'],[['Pot before your call is €80; call costs €20. Required equity?','€20/(€80+€20) = 20%.'],['Why is €20/€80 = 25% not the required equity here?','The final pot includes your call: €100. Do not leave that €20 out.'],['At 30% equity for this €20 call, what is net EV?','0.30 × €100 − €20 = +€10, ignoring rake and future betting.'],['What assumptions make this simple call calculation valid?','Equity is estimated well and realized fully; no extra bets or rake change the payoffs.'],['Pot €60 before a €30 call. Required equity?','€30/€90 = 33.33%.'],['A drawing hand has 20% chance to improve but not always win when it improves. Is 20% improvement automatically 20% equity?','No. Some improved hands lose; equity measures expected pot share, including ties.']],'required equity = call/(pot+call)',[['20/(80+20)*100',20]]);
// Beginner arithmetic and practical decisions.
r(2,'arithmetic','fractions','Fractions as percentages',['A fraction is a part divided by a whole.','Common fractions speed up mental probability and rate calculations.','Divide numerator by denominator; multiply by 100 for percent.','One of four equal slices is a quarter of the whole.'],[['What are 1/4 and 3/4 as percentages?','25% and 75%.'],['Is 1/3 exactly 33%?','No. It is 33.333…%; 33% is a rounded approximation.'],['What are 1/5 and 1/8?','20% and 12.5%.'],['When is rounding a fraction dangerous?','Near a decision threshold, especially when the claimed edge is smaller than the rounding error.'],['Seven wins from 20 independent trials give what observed win fraction?','7/20 = 35%. This is an observed rate, not guaranteed true probability.'],['A stake needs 1/6 equity. Is a 16% estimate enough?','No: 1/6 ≈ 16.67%, so 16% is below break-even before costs.']],'fraction = numerator/denominator',[['1/8*100',12.5]]);
r(2,'arithmetic','negative-returns','Negative returns',['A loss written as a negative fraction of starting value.','It keeps wins and losses in the same arithmetic.','Ending value = starting value × (1 + return).','A −10% return leaves 90 of each starting 100.'],[['€400 suffers a −25% return. What remains?','€400 × 0.75 = €300.'],['Can a fully paid unlevered asset lose more than 100% of its invested amount?','Not from price falling to zero alone. Leverage and other obligations can create larger losses.'],['What return takes €250 to €200?','(200−250)/250 = −20%.'],['Before averaging positive and negative percentages, what matters?','Whether they describe comparable periods or different amounts; compound growth uses products.'],['A −100% return leaves how much of €80?','€0. Recovering by percentage growth from zero is impossible.'],['Why can +25% after −25% fail to restore capital?','€100 × 0.75 × 1.25 = €93.75; the gain applies to a smaller base.']],'V_end = V_start(1+r)',[['100*.75*1.25',93.75]]);
r(2,'arithmetic','discount-chain','Successive discounts',['Two discounts apply one after another to changing prices.','It avoids adding reductions as though both used the same base.','Multiply the remaining-price factors: (1−d 1)(1−d 2).','The second cut removes a slice of the smaller remaining cake.'],[['A €100 price has 20% off, then 10% off. Final price?','€100 × 0.8 × 0.9 = €72; total discount 28%.'],['Why is this not a 30% discount?','The 10% cut is €8 from €80, not €10 from the original €100.'],['Two 50% discounts remove what share?','75%; 25% remains.'],['What should a price comparison include beyond discount percentages?','The starting price and all taxes/fees, since the cheapest percentage can still have a higher final price.'],['A €200 price rises 10% then falls 10%. Final price?','€200 × 1.1 × 0.9 = €198, a 1% loss.'],['What single discount equals 25% off followed by 20% off?','40%: 1 − 0.75 × 0.8 = 0.40.']],'net discount = 1−(1−d 1)(1−d 2)',[['1-.75*.8',.4]]);
r(2,'arithmetic','weighted-average','Weighted average',['An average that gives different amounts of importance to different values.','It combines groups or returns without treating a tiny group like a large one.','Σ(weight × value) ÷ Σ weights.','Ten votes from one group count more than one vote from another.'],[['80 people average €10 spending; 20 average €30. Overall average?','(80×€10 + 20×€30)/100 = €14.'],['Why is (€10+€30)/2 = €20 wrong here?','The groups are unequal. It gives each group 50% weight instead of 80% and 20%.'],['What is the mean of values 5 and 15 with equal weights?','10. Equal weights give the ordinary average.'],['When merging conversion rates, what weights should you use?','The denominators, such as visits, not the number of groups.'],['A portfolio is 75% in a +10% asset and 25% in a −10% asset. Same-period return?','0.75×10% + 0.25×(−10%) = +5%, before costs and cash flows.'],['Group A: 10/100 buyers; B: 20/400. Combined conversion?','30/500 = 6%, not the unweighted average 7.5%.']],'weighted mean = Σwv/Σw',[['(80*10+20*30)/100',14],['30/500*100',6]]);
r(2,'arithmetic','rates','Rates and denominators',['A quantity per unit, such as euros per hour or purchases per visit.','It compares efficiency and avoids confusing bigger totals with better performance.','Rate = amount ÷ exposure, using consistent units.','Speed compares meters travelled with seconds used, not meters alone.'],[['Earn €120 in six hours. What is the hourly rate?','€20 per hour.'],['Does a shop with 200 sales outperform one with 100 sales in conversion?','Not necessarily. The visitor counts may differ.'],['Travel 600 meters in 120 seconds. What is the speed?','5 meters per second.'],['What makes two rates comparable?','Matching denominators, units, periods and what counts as an event.'],['An ad costs €60 and brings 30 buyers. Cost per buyer?','€2 per buyer.'],['A server handles 1,000 requests in 10 seconds; another 900 in five. Which rate is higher?','Second: 180 requests/s versus 100, an 80% higher rate.']],'rate = amount/exposure',[['900/5',180]]);
r(2,'decisions','break-even','Break-even win probability',['The winning chance at which expected net profit is zero.','It tells you the minimum probability required by a payoff price.','For win W and loss L, p = L/(W+L), before costs.','A larger prize can compensate for a lower winning chance.'],[['Win €40 or lose €10. What win probability breaks even?','10/(40+10) = 20%.'],['If the win rate equals break-even before fees, is the trade profitable after fees?','No. Positive fees make net EV negative.'],['Win €10 or lose €40. Required win probability?','40/50 = 80%.'],['When does this two-outcome formula need adjustment?','When there are fees, ties, partial outcomes or changing payoff sizes.'],['Win €20 or lose €10; pay €2 every try. What p breaks even?','20 p −10(1−p)−2=0; p=12/30=40%.'],['A 35% estimate faces a 40% cost-adjusted threshold. What does the model imply?','Negative EV, if those estimates and costs are correct.']],'p_BE = (L+fixed cost)/(W+L)',[['12/30*100',40]]);
r(2,'decisions','decimal-ev','Expected return at decimal odds',['Expected net profit per unit stake at a stated price.','It turns the gap between your probability and the offered price into a money edge.','Net EV per €1 = p × D − 1, for win probability p and decimal odds D.','A €1 ticket returns D only if it wins, but costs €1 in every case.'],[['Estimated p=40%, decimal odds 3.00. Expected ROI before costs?','0.4×3−1 = 0.20 = +20% of stake.'],['Why is (40%−33.33%) not the expected ROI?','That is a probability gap. ROI also depends on the payout multiplier.'],['At p=25%, odds 4.00, what is EV?','0.25×4−1 = 0: break-even before costs.'],['Which probability should enter this formula?','A defensible estimate, not the same price-implied probability presented as independent evidence.'],['At p=55%, odds 1.80, find EV on €100.','(0.55×1.8−1)×€100 = −€1, or −1%.'],['Odds 3.00 and an uncertain p between 30% and 40%. Can the sign change?','Yes. ROI ranges from −10% to +20%; the probability estimate determines the decision.']],'ROI_EV = p D−1',[['(.55*1.8-1)*100',-1]]);
r(2,'decisions','money-risk','Risk tolerance and EV',['A money average alone does not describe how painful losses can be.','It prevents a small average advantage from threatening essential capital.','Compare expected reward with loss sizes, liquidity needs and your ability to survive.','A bridge can be profitable on average but useless if one load breaks it.'],[['A gamble offers EV +€10 but can lose your entire €1,000 reserve. Is EV alone enough?','No. The possible loss and need for that reserve matter.'],['Does high EV always mean low risk?','No. A larger upside can create high EV alongside severe downside.'],['Which is easier to survive: ten separate €10 risks or one €100 risk?','It depends on dependence and bankroll rules; equal nominal risk does not guarantee equal loss distributions.'],['What must be decided before risking necessary cash?','A tolerable loss limit and whether the money is needed for obligations.'],['You have €500 and stake €400. What share is exposed?','80%, even if the model estimates a positive edge.'],['Two equal-EV projects require €100 and €10,000 capital. Why can the smaller one be preferable?','Less capital is tied up, and failure may be easier to absorb. Compare return on capital and alternatives.']],'EV and risk are separate dimensions',[['400/500*100',80]]);
r(2,'decisions','decision-tree','Decision tree',['A branching map of choices and uncertain outcomes.','It keeps multi-step payoffs and probabilities explicit.','Work backward: average chance branches; choose among feasible decision branches.','At a fork you choose a road; at a coin flip nature chooses the branch.'],[['A product launch has 30% chance of €100 and 70% chance of €0, with €20 cost. EV?','0.3×€100−€20 = +€10.'],['Should you average your two available choices as if each happens with 50% probability?','No. You choose one; average only chance outcomes with appropriate probabilities.'],['If a branch happens 50% of the time and succeeds 20% within that branch, joint chance?','0.5×0.2 = 10%.'],['Before multiplying branch probabilities, what must you check?','The second probability is conditional on reaching the first branch.'],['Test costs €5 and raises expected later net payoff from €10 to €18. Net value of testing?','€18−€10−€5 = €3.'],['Why can a tree be misleading even with correct arithmetic?','Missing outcomes, wrong conditional chances or impossible choices can make the model wrong.']],'joint branch probability = p(first) × p(second|first)',[['.5*.2*100',10]]);
r(2,'decisions','uncertain-probability','Uncertain probability estimates',['Your estimated chance can itself be wrong.','It encourages sizing and decisions that survive estimation error.','Recalculate EV over a plausible probability range.','The fuel gauge has an error bar; a reading just above empty is not a safe long trip.'],[['At odds 2.00, p is estimated 55% but might be 45%. What EV range per €1?','2×0.45−1 = −€0.10 to 2×0.55−1 = +€0.10.'],['Does 100% confidence in a spreadsheet make its input p correct?','No. Calculation certainty does not remove estimation uncertainty.'],['Which estimate is farther above a 50% threshold: 51% or 60%?','60%; gaps are 1 and 10 percentage points.'],['What evidence supports a narrow probability range?','Enough representative, independent data and a calibrated model tested outside its fitting data.'],['Win €30 or lose €10. If p ranges 20%–30%, EV range?','40 p−10 gives −€2 to +€2.'],['A 1% edge disappears after a 2-percentage-point p revision at odds 2.00. What does that suggest?','The decision is fragile; a small input revision changes expected ROI by 4 percentage points.']],'sensitivity: ΔROI = D × Δp',[['40*.2-10',-2],['40*.3-10',2]]);
r(2,'applications','bluff-threshold','Break-even poker bluff',['The fold frequency needed for a bluff with no equity when called to break even.','It prices the risk of a pure bluff instead of assuming aggression is profitable.','Required fold probability = bet/(pot + bet), with no rake and zero called equity.','You risk the bet to win the existing pot; called bluffs lose that bet.'],[['Bet €50 into €100 with zero equity when called. Required folds?','50/(100+50) = 33.33%.'],['Why not divide the bet by the final called pot?','This bluff either wins the existing €100 or loses €50. The payoff equation is different from calling.'],['Bet €100 into €100. Required fold rate?','50%.'],['What assumption changes the pure-bluff threshold?','Having equity when called, rake, later betting or different fold responses.'],['At 40% folds, bet €50 into €100. EV?','0.4×€100−0.6×€50 = +€10.'],['If larger bets induce more folds, should bet size be chosen using one fixed fold rate?','No. Model how the opponent responds to each size; the probability can change.']],'f_BE = B/(P+B)',[['.4*100-.6*50',10]]);
r(2,'applications','outs','Poker outs and drawing probability',['Outs are unseen cards that would improve a hand as intended.','They approximate drawing chances, with attention to cards that may still lose.','One-card hit chance = clean outs/unseen cards. Two-card misses multiply conditional miss rates.','Drawing one of nine useful cards from 47 unseen cards is about one chance in five.'],[['Nine clean outs among 47 unseen cards. Chance on the next card?','9/47 ≈ 19.15%.'],['Why can counting every apparent improving card overstate winning chances?','Some outs may be blocked or give an opponent a better hand. Improvement is not always a win.'],['Eight outs among 46 unseen cards. Next-card chance?','8/46 ≈ 17.39%.'],['When does the rule of 4 and 2 become only approximate?','Always; it approximates small drawing probabilities and can be poor for many outs or complicated hands.'],['Nine fixed clean outs with two cards to come from 47. Hit at least once?','1−(38/47)×(37/46) ≈ 34.97%, assuming both cards are seen without extra cost.'],['Why is comparing two-card odds with a one-card call price unsafe?','You may have to pay again to see the second card, and your outs or opponent range may change.']],'P(hit by two cards)=1−P(miss first)P(miss second|miss first)',[['(1-38/47*37/46)*100',34.967622571692876,1e-8]]);
r(2,'applications','position-size','Risk-based position size',['A position amount calculated from a risk budget and assumed loss per unit.','It links trade size to the possible cash loss rather than confidence alone.','Units = risk budget ÷ assumed loss per unit; include costs where relevant.','A €100 budget buys 50 units of €2 risk, not 100 units.'],[['Risk budget €100, entry €20, stop €18. Units before costs?','€100/€2 = 50 units; position value €1,000.'],['Does the stop ensure the maximum loss is exactly €100?','No. Gaps, halts and slippage can produce a worse fill.'],['If per-unit assumed loss doubles, what happens to position size at the same budget?','It halves.'],['What should be checked before relying on the size formula?','Fill risk, liquidity, costs, leverage and exposure to the same event in other positions.'],['Bankroll €5,000, budget 1%, assumed loss €0.50/share. Units?','Budget €50; 100 shares before costs.'],['A stressed fill would lose €3/share instead of €2. What do 50 shares lose?','€150, 50% more than the planned €100.']],'units = budget/risk per unit',[['5000*.01/.5',100]]);
r(2,'applications','overround','Bookmaker overround',['The sum of all mutually exclusive outcome implied probabilities above 100%.','It shows that market prices cannot all be fair probabilities at once.','Compute Σ(1/odds); overround = that sum − 1.','A pie labelled 110% contains overlapping price markups, not extra probability.'],[['A two-outcome market offers 1.80 on each side. Overround?','2/1.8−1 ≈ 11.11%.'],['Does 11.11% overround equal the bookmaker’s guaranteed realized profit?','No. Actual profit depends on stakes, results and book balance; overround is a price measure.'],['Normalize the two 1.80 prices by proportional no-vig adjustment. Probabilities?','50% each: both raw 55.56% values divided by their 111.11% total.'],['Which outcomes must be included?','All mutually exclusive, exhaustive results, with consistent settlement rules.'],['Odds 2.00 and 1.80 imply what total?','50% +55.56% =105.56%, an overround of 5.56%.'],['Does proportional no-vig adjustment reveal the true chance?','No. It is one allocation assumption for removing margin, not a verified probability model.']],'overround = Σ1/D −1',[['(2/1.8-1)*100',100/9]]);
// Advanced beginner: compounding and Kelly, introduced in small steps.
r(3,'arithmetic','drawdown-recovery','Loss recovery',['The gain needed to recover after a percentage loss.','It explains why deep drawdowns are costly even when later gains look large.','For loss d, required gain = d/(1−d), where 0≤d<1.','After half the water leaks out, you must add the entire remaining half again.'],[['A 50% loss needs what recovery gain?','100%: €100→€50 needs €50/€50.'],['Why does a 20% gain not reverse a 20% loss?','The gain is applied to the smaller €80 base; €80×1.2=€96.'],['What gain repairs a 10% loss?','0.10/0.90 ≈ 11.11%.'],['Why does the formula fail at a 100% loss?','No capital remains; recovery by multiplying zero is impossible.'],['A 40% drawdown leaves €600 from €1,000. Required recovery?','€400/€600 =66.67%.'],['Which is harder to repair: 50% or 80% loss?','50% needs +100%; 80% needs +400%. Deep losses create sharply larger recovery hurdles.']],'g_recovery = d/(1−d)',[['.4/.6*100',200/3]]);
r(3,'arithmetic','compound-return','Compound return',['Growth from multiplying each period’s return factor.','It measures what actually happens to reinvested capital.','Final/start = Π(1+r); total return = product −1.','Each rise changes the base used by the next rise.'],[['Two +10% periods grow €100 to what?','€100×1.1×1.1=€121, total +21%.'],['Why not simply report +20% compound growth?','The second 10% also earns on the first €10 gain.'],['A +20% period followed by −20% has what total return?','1.2×0.8−1 =−4%.'],['When can multiplying returns ignore cash flows incorrectly?','When deposits or withdrawals occur; choose a return method that handles their timing.'],['Three +5% periods produce what total gain?','1.05³−1=15.7625%, about 15.76%.'],['Do +10% then −5% and −5% then +10% produce different final wealth without cash flows?','No. Both multiply by 1.1×0.95=1.045, a +4.5% total. Path risk can still differ.']],'R_total = Π(1+r_t)−1',[['1.05**3-1',.157625]]);
r(3,'arithmetic','geometric-mean','Geometric average return',['The constant per-period return giving the same compounded wealth.','It captures growth after volatility instead of just averaging percentages.','Geometric return = (product of return factors)^(1/n)−1.','A smooth staircase reaches the same height as an uneven path with the same final wealth.'],[['Returns +50% and −50%. Arithmetic and total compound return?','Arithmetic average 0%; compound total 1.5×0.5−1=−25%.'],['Why is a zero arithmetic average not proof that wealth stayed flat?','Loss and gain percentages use changing bases; compounding multiplies factors.'],['For these two periods, what is the geometric average return?','√0.75−1≈−13.40% per period.'],['What assumptions matter when interpreting a geometric mean?','Positive wealth factors, consistent periods and appropriate treatment of cash flows.'],['Two periods compound to +21%. Constant per-period rate?','√1.21−1=10%.'],['Why can a steadier strategy grow wealth faster despite the same arithmetic mean?','Lower volatility reduces the loss from multiplying uneven return factors, under comparable conditions.']],'g = (Π(1+r))^(1/n)−1',[['Math.sqrt(.75)-1',-.1339745962155614]]);
r(3,'arithmetic','cagr','Compound annual growth rate',['The constant annual rate connecting beginning and ending value.','It compares multi-year growth over different holding periods.','CAGR=(ending/beginning)^(1/years)−1, without intervening cash flows.','Replace an uneven journey with the same steady yearly growth.'],[['€100 becomes €121 in two years. CAGR?','(121/100)^(1/2)−1=10%.'],['Is +50% total over five years a +10% CAGR?','No. 1.5^(1/5)−1≈8.45%.'],['€100 doubles over ten years. CAGR?','2^(1/10)−1≈7.18%.'],['Why can deposits invalidate a simple CAGR profit claim?','Deposits increase ending wealth without being investment return. Separate cash flows.'],['€1,000 becomes €800 after two years. CAGR?','0.8^(1/2)−1≈−10.56%.'],['Two funds have equal CAGR. Must they have equal risk?','No. The paths, drawdowns, liquidity and uncertainty can differ greatly.']],'CAGR = (V_end/V_start)^(1/t)−1',[['2**.1-1',.07177346253629313]]);
r(3,'arithmetic','doubling','Doubling time',['The time needed for a growing amount to reach twice its starting value.','It gives a quick sense of the scale of compound growth.','Exact discrete time = ln 2/ln(1+r); rule of 72 uses about 72/r_percent years.','Repeated growth builds on the gains already earned.'],[['At 8% yearly growth, roughly how long to double using 72?','72/8=9 years.'],['Is the rule of 72 exact or a guarantee?','Neither. It approximates constant compound growth; realized returns can differ.'],['At 6% and 12%, what are approximate doubling times?','12 years and six years. Doubling the rate roughly halves the time.'],['What assumption must hold for the exact time formula?','A constant positive per-period compound rate; no unmodelled cash flows.'],['What is the exact doubling time at 10% annual compound growth?','ln 2/ln 1.1≈7.27 years.'],['Would “10% average return” alone establish a 7.27-year doubling time?','No. Specify geometric compound rate, fees and whether growth persists; an arithmetic average can mislead.']],'t_double = ln 2/ln(1+r)',[['Math.log(2)/Math.log(1.1)',7.272540897341713]]);
r(3,'decisions','kelly-purpose','Kelly’s objective',['Choose a stake fraction to maximize expected logarithmic wealth growth under a specified model.','It connects a genuine edge with long-run bankroll sizing.','Kelly optimizes growth, not the next win or the smallest drawdown.','Betting everything can have attractive one-shot EV but destroys future growth after a loss.'],[['Does Kelly aim to maximize the probability of winning the next bet?','No. It chooses stake size to maximize expected log growth under the model.'],['“Kelly guarantees that the bankroll grows.” What is wrong?','Outcomes are uncertain; drawdowns happen, and wrong probabilities can make the suggested stake harmful.'],['How can a larger stake have higher money EV but lower expected log growth?','The larger loss damages remaining wealth disproportionately, lowering compounded growth.'],['What inputs must be credible before using Kelly?','Winning probability, net odds, loss exposure and how bets are related.'],['At even-money odds with p=50%, should a no-short Kelly bettor stake a positive fraction?','No. There is no edge; the optimum is zero.'],['Why start learning Kelly with a simple binary bet?','It isolates probability, odds and fraction before correlated portfolios and uncertain outcomes complicate sizing.']],'maximize E[ln(final wealth)]');
r(3,'decisions','kelly-formula','Binary Kelly fraction',['The growth-optimal fraction for a win/loss bet with known probabilities and stated payoffs.','It provides a starting sizing model for repeated independent opportunities.','f=(bp−q)/b, with b=net winning odds, p=win chance and q=1−p.','At even money, a 60/40 edge gives a 20% model-optimal fraction, not a 60% stake.'],[['At p=60%, decimal odds 2.00, calculate full Kelly.','b=1, q=0.4; f=(1×0.6−0.4)/1=20%.'],['Why is b not 2 at decimal odds 2.00?','b is net profit per unit stake. The returned stake is not profit, so b=2−1=1.'],['At p=40%, decimal odds 3.00, calculate Kelly.','b=2; f=(2×0.4−0.6)/2=10%.'],['Which assumptions limit this simple result?','Known stable p and payouts, fractional stakes, full stake loss on failure, no extra costs or constraints; related bets need joint sizing.'],['With €1,000 bankroll and full Kelly 10%, what stake is suggested by the model?','€100.'],['A model gives p=51% at even money. If true p is 49%, what goes wrong?','The estimated 2% stake is placed on a negative edge. Estimated Kelly is only as good as the inputs.']],'f*=(bp−(1−p))/b',[['(2*.4-.6)/2',.1]]);
r(3,'decisions','fractional-kelly','Half and quarter Kelly',['Stake a chosen fraction of the full Kelly result.','It reduces exposure and makes sizing less aggressive when estimates are uncertain.','Half Kelly=0.5 f; quarter Kelly=0.25 f. Compute full Kelly using net odds first.','Turn a high growth setting down to reduce the bumps in the path.'],[['Full Kelly is 20%. What are half and quarter Kelly?','10% and 5% of bankroll.'],['Does half Kelly eliminate risk or model error?','No. It reduces exposure; a wrong edge can still lose money.'],['For a €2,000 bankroll, what stake is quarter of a 20% Kelly fraction?','5% of €2,000 =€100.'],['Why might lower fractions be considered with noisy edge estimates?','Sizing based on an overestimated edge can overbet; smaller fractions provide some margin for error.'],['Full Kelly is 8%. What is half Kelly on €500?','4%×€500=€20.'],['Can you apply half Kelly separately to ten correlated bets and assume the total is conservative?','No. Related losses can occur together; joint exposure must be checked.']],'f_fractional = multiplier × f_full',[['.5*.08*500',20]]);
r(3,'decisions','bankroll-definition','Bankroll and changing stakes',['Capital assigned to the strategy, distinct from a single stake or target profit.','It defines the base for fraction-based sizing and separates essential cash.','Stake=f×current defined bankroll; reassess after actual wealth changes.','A 5% slice of a shrinking pie gets smaller.'],[['Bankroll falls €1,000→€800. At 5% sizing, stake changes how?','€50→€40, a 20% reduction.'],['Why is using the hoped-for payout as bankroll a mistake?','Unwon money is not available capital and inflates the sizing base.'],['Fixed €50 stakes at bankroll €1,000 and €500 expose what fractions?','5% and 10%; the same cash stake becomes twice as aggressive.'],['What needs defining before applying a bankroll rule?','Available strategy capital, withdrawals, reserve needs and losses from concurrent positions.'],['After €1,000 earns 10%, a 2% stake is what?','2% of €1,100 =€22.'],['Does changing the bankroll after every outcome fix an incorrectly positive edge estimate?','No. Dynamic sizing controls exposure but cannot create an edge.']],'stake = f × current bankroll',[['.02*1100',22]]);
r(3,'decisions','negative-kelly','Zero and negative Kelly',['A non-positive model-optimal fraction signals no positive stake in the stated direction.','It prevents treating any calculated number as a reason to bet.','For a no-short binary bet, use zero when computed f≤0; reverse betting requires its own payoff model.','A price can be too expensive even for a likely winner.'],[['p=45% at even money. Full Kelly before constraints?','2 p−1=−10%; a no-short bettor stakes zero.'],['Should a negative Kelly fraction mean secretly borrow and bet the opposite side?','No. The other side may have a different price, fees and risks; calculate it separately.'],['p=50% at even money gives what fraction?','0%.'],['What must be included before labeling an apparent edge positive?','Net payout, realistic p and all unavoidable costs.'],['p=30%, decimal odds 3.00. What is Kelly?','(3×0.3−1)/(3−1)=−5%; no positive stake in this direction.'],['An estimated p crosses the break-even value under a plausible revision. What is the sizing lesson?','The edge sign is uncertain; the point-estimate fraction is fragile, not established profit.']],'no-short fraction = max(0,f*)',[['(3*.3-1)/2',-.05]]);
r(3,'applications','implied-odds','Poker implied odds',['Possible additional money won later if a drawing hand improves.','It adds realistic future payoffs to a call calculation.','Model both extra winnings and extra losses; future payoff is uncertain.','A cheap ticket may open a chance at a bigger prize, but the prize is not promised.'],[['Call €10; 20% chance to win €30 net, otherwise lose €10. EV?','0.2×€30−0.8×€10=−€2.'],['“He has €500 behind, so I will win all €500 if I hit.” What is wrong?','Stack size is not a guaranteed future payment; the opponent may fold or have a better hand.'],['If winning net payoff rises to €50 at the same 20% chance, what is EV?','0.2×€50−0.8×€10=+€2.'],['What can create reverse implied odds?','Improving into a second-best hand and losing additional money.'],['With 20% success and €10 loss otherwise, what net win breaks even?','W solves 0.2 W−8=0, so €40.'],['Why should implied odds depend on position and opponent behavior?','They affect whether later bets are paid and whether equity can be realized cheaply.']],'EV = p W−(1−p)L',[['.2*50-.8*10',2]]);
r(3,'applications','roi','ROI and stake turnover',['Profit divided by total amount staked or invested under a stated definition.','It distinguishes bankroll growth from return on a large volume of repeated stakes.','ROI=net profit/total stake; label the denominator and period.','The same €100 can circulate through many bets, so turnover can exceed bankroll.'],[['€500 profit on €10,000 total stakes. ROI?','5%.'],['Does 5% ROI on stakes mean the bankroll grew 5%?','No. If starting bankroll was €1,000, €500 profit is 50% bankroll growth before cash flows.'],['€100 profit on €2,000 stakes versus €200 on €10,000. Which has higher ROI?','First: 5% versus 2%, though the second earns more cash.'],['What should a reported ROI include?','All settled outcomes, commissions and the defined stake exposure; exclude selection of only winning bets.'],['A bettor stakes €50 on 100 bets and profits €150. ROI?','€150/€5,000=3%.'],['Can small-sample high ROI alone establish a profitable long-run strategy?','No. Variance, selection and changing conditions may explain it; examine uncertainty and out-of-sample records.']],'ROI = profit/total stake',[['150/(50*100)*100',3]]);
r(3,'applications','slippage','Slippage and transaction costs',['The difference between an expected execution price and the actual fill.','It changes realized trading returns, especially where liquidity is thin.','Compare actual net proceeds and costs with the planned prices; include both entry and exit.','The price tag can move before the order reaches the counter.'],[['Planned buy €10; actual fill €10.05 for 200 shares. Extra entry cost?','€0.05×200=€10, or 0.5% of the planned €2,000 position.'],['Is a limit order guaranteed to fill at its limit?','No. It constrains price if filled, but execution can be partial or absent.'],['A €20 gross profit with €8 fees and €15 adverse slippage leaves what?','−€3 net.'],['Why measure slippage on losing trades too?','Ignoring difficult exits understates costs and overstates strategy EV.'],['Sell 100 shares at €9.90 rather than expected €10.00. Revenue shortfall?','€10, a 1% price shortfall.'],['Why can increasing trade size erase an apparent backtest edge?','More size may consume worse prices, reduce fill probability and raise market impact.']],'net P&L = gross P&L − fees − execution cost',[['20-8-15',-3]]);
// Early intermediate.
r(4,'arithmetic','relative-base','Changing the comparison base',['A relative difference changes when its denominator changes.','It explains asymmetric price, salary and performance comparisons.','State which value is the base before dividing a difference.','A €20 gap looks bigger beside €80 than beside €100.'],[['€100 is how much higher than €80?','€20/€80=25% higher.'],['“If A is 25% above B, B is 25% below A.” Why wrong?','Different bases. B is 20% below A in the €100/€80 example.'],['If A is twice B, how far below A is B?','50% below A; A is 100% above B.'],['What must a competitor-price percentage identify?','The comparison product’s price, currency, taxes and equivalent quantity.'],['Cost falls €120→€100. Percent reduction and reverse rise?','16.67% reduction; the reverse is 20% growth.'],['A study reports risk “50% higher” but starts at 2%. New risk and absolute change?','3% risk; +1 percentage point.']],'relative difference = (A−B)/comparison base',[['(120-100)/120*100',50/3]]);
r(4,'arithmetic','indexing','Index numbers',['Values rescaled so a chosen starting value equals 100.','They compare growth paths of differently sized quantities.','Index = current/base ×100, with a nonzero base.','Set every runner’s start at the same line before comparing distance gained.'],[['Revenue €400→€500, base index 100. New index?','125, representing +25% growth.'],['Does index 150 mean revenue is €150?','No. It means 50% above the chosen base.'],['An index falls 120→108. What is the return?','108/120−1=−10%, not −12%.'],['What must match when comparing two indexed paths?','Base date, return definition, currency and inclusion of dividends or costs.'],['An asset index goes 100→80→100. What are the two period returns?','−20% then +25%.'],['One firm starts twice as large; both end at index 130. Which has greater absolute growth?','The larger firm, if measured in the same units: both grew 30%, but its base was twice as large.']],'index = 100 × current/base',[['108/120-1',-.1]]);
r(4,'arithmetic','unit-conversion','Consistent units',['Expressing quantities on the same scale before calculating.','It prevents 100-fold or 1,000-fold errors in rates and prices.','Carry units through the equation and convert once explicitly.','Measuring one box in meters and another in centimeters makes the numbers incomparable.'],[['A price is €0.02 per request. Cost for 1,000 requests?','€20.'],['A 1% rate is entered as 1 in a decimal-return formula. Error factor?','100-fold; 1% is 0.01, while 1 means 100%.'],['A speed is 3 meters/second. Distance in two minutes?','3×120=360 meters.'],['What should you check before annualizing a daily number?','Whether days mean calendar or trading days, and whether the quantity adds or compounds.'],['A spread is 5 basis points. Percentage?','0.05%; 100 basis points equal 1 percentage point.'],['A risk difference is 0.002 in decimal units. What is it in percentage points?','0.2 percentage points, or 20 basis points.']],'1 percentage point = 100 basis points',[['3*120',360]]);
r(4,'arithmetic','log-return','Logarithmic return',['The natural logarithm of the ending-to-starting value ratio.','It adds across periods and connects finance with continuous growth models.','Log return = ln(V_end/V_start), for positive values.','Instead of multiplying growth factors, logs turn the journey into additions.'],[['A +10% simple return gives what log return?','ln 1.1≈0.09531, or 9.531% in log units.'],['Is a 10% simple return exactly a 10% log return?','No. They are close only for small changes.'],['What is the simple return corresponding to log return 0.10?','e^0.10−1≈10.517%.'],['When is the log return undefined?','When a price or wealth ratio is non-positive.'],['Price goes €100→€110→€121. Total log return?','ln 1.1+ln 1.1=ln 1.21≈0.19062; simple total +21%.'],['Can averaging log returns ignore bankruptcy risk?','No. Zero wealth gives log wealth −∞; an assumed positive-value model must not hide possible ruin.']],'l = ln(1+r); r=e^l−1',[['Math.log(1.1)',.09531017980432493]]);
r(4,'arithmetic','real-return','Inflation-adjusted return',['Growth in purchasing power rather than the currency amount alone.','It compares what the investment can buy after prices rise.','Real return = (1+nominal)/(1+inflation)−1.','More euros do not buy more goods if goods prices rise equally fast.'],[['Nominal return 10%, inflation 5%. Exact real return?','1.10/1.05−1≈4.76%.'],['Why is simply subtracting inflation only approximate?','The exact calculation compares growth factors; subtraction ignores their interaction.'],['Nominal growth and inflation both 6%. Real growth?','0%.'],['What inflation measure should be used?','One matching the period and relevant purchasing basket; personal costs can differ from headline inflation.'],['Nominal return 2%, inflation 4%. Real return?','1.02/1.04−1≈−1.92%.'],['A fund reports 8% nominal before a 1% proportional annual fee; inflation 3%. Real after-fee growth?','1.08×0.99/1.03−1≈3.81%, under that fee timing assumption.']],'r_real=(1+r_nominal)/(1+inflation)−1',[['1.1/1.05-1',1/21],['1.08*.99/1.03-1',.038058252427184414]]);
r(4,'decisions','utility','Expected utility',['The probability-weighted value of outcomes after accounting for preferences.','It allows risk aversion or essential needs to matter beyond cash EV.','Choose by E[u(wealth)], specifying the utility function and feasible choices.','The first €100 for food can matter more than an extra €100 after you are comfortable.'],[['Why can a risk-averse person reject a fair ±€100 gamble?','A loss can hurt more than an equal gain helps at their current wealth.'],['Is utility necessarily equal to euros?','No. Utility is a preference scale; different people or contexts may value outcomes differently.'],['For linear utility u(W)=W, how does the ranking compare with money EV?','It is the same, under that model.'],['What should be checked before a utility calculation guides a decision?','The function reflects actual preferences, constraints and which wealth is relevant.'],['A gamble ends at €25 or €225 equally likely. Money EV?','€125.'],['Why might the same €125 average not feel equal to guaranteed €125?','The uncertain low outcome may be costly; concave utility penalizes that spread.']],'expected utility = Σ p_i u(W_i)',[['.5*25+.5*225',125]]);
r(4,'decisions','concave-utility','Concave wealth utility',['A model in which each extra euro adds less value than the previous euro.','It explains risk aversion with an explicit mathematical preference.','For concave u, u(E[W])≥E[u(W)] when expectations exist.','One large meal is less useful than spreading food across hungry days.'],[['Use u(W)=√W. Equal chances of €25 and €225 give expected utility?','0.5×5+0.5×15=10.'],['Does expected utility 10 mean €10 expected wealth?','No. Utility units differ from euros; expected wealth here is €125.'],['What utility does guaranteed €100 give?','√100=10, the same as this gamble.'],['What domain constraint applies to square-root utility?','Wealth must be non-negative.'],['What utility does guaranteed expected wealth €125 give?','√125≈11.18, higher than the gamble’s 10.'],['What does this example show about risk?','With this concave utility, guaranteed mean wealth is preferred to uncertain wealth with the same mean.']],'u(W)=√W',[['.5*Math.sqrt(25)+.5*Math.sqrt(225)',10]]);
r(4,'decisions','certainty-equivalent','Certainty equivalent',['The guaranteed payoff or wealth giving the same utility as a gamble.','It expresses risk preferences in money rather than utility units.','Solve u(CE)=E[u(W)]. Risk premium = E[W]−CE under matching definitions.','Replace a bumpy prize with a smooth cash amount you value equally.'],[['For square-root utility, expected utility 10 means what certainty-equivalent wealth?','€100, since √100=10.'],['Is CE always the expected money outcome?','No. Risk aversion usually makes CE smaller; preferences determine the difference.'],['If expected wealth is €125 and CE is €100, what is the risk premium?','€25, or 20% of the €125 expected wealth.'],['What must match before subtracting CE from EV?','Both must describe the same wealth or payoff scale and starting position.'],['Guaranteed €80 versus a gamble with CE €75. Which is preferred under that utility?','Guaranteed €80.'],['Why can two people assign different CEs to the same gamble?','They can have different utility functions, wealth, obligations and alternatives.']],'CE=u⁻¹(E[u(W)])',[['(125-100)/125*100',20]]);
r(4,'decisions','information-value','Value of information',['The improvement in expected decision value from learning before choosing.','It prices research, testing and forecasts by how they change action.','Information value = best expected value with the signal − best without it, before signal cost.','A weather report helps only if it changes which route or equipment you choose.'],[['Information increases best expected profit €40→€55 but costs €10. Net value?','€55−€40−€10=€5.'],['Does a more accurate forecast always have large decision value?','No. If it never changes the best action, its decision value can be zero.'],['What is the difference between free and net information value?','Net value subtracts acquisition, time and implementation costs.'],['How do you avoid overstating a signal’s value?','Account for signal errors and condition each action on the information actually received.'],['A €5 test prevents an expected €8 loss without changing benefits. Net value?','€3.'],['Can information with positive value still be a poor purchase?','Yes, if its price or delay costs exceed the expected improvement.']],'net VOI = EV_with − EV_without − cost',[['55-40-10',5]]);
r(4,'decisions','perfect-information','Expected value of perfect information',['The upper-bound improvement from knowing the relevant state before acting.','It caps how much an imperfect test could be worth in the same decision model.','EVPI=E[best payoff with state known]−best expected payoff without it.','A perfect map lets you avoid every bad road; a real map can do no better than that.'],[['Project succeeds 40% for +€100, otherwise −€50; skipping pays zero. Best value without information?','EV=0.4×100−0.6×50=€10, so accept by money EV.'],['Can an imperfect signal be worth more than perfect state knowledge here?','Not within the same payoff model and cost-free information assumptions.'],['With perfect knowledge, accept only successes. Expected payoff?','0.4×€100=€40.'],['What must remain the same when comparing perfect and imperfect information?','Available actions, payoffs, timing and state distribution.'],['For this project, what is EVPI?','€40−€10=€30.'],['A proposed imperfect test costs €35. Can it pay for itself in this model?','No. Even perfect information is worth only €30 before costs.']],'EVPI=E[max_a payoff(a,state)]−max_a E[payoff]',[['.4*100-.6*50',10]]);
r(4,'applications','sports-kelly','Kelly sizing for a sports price',['Convert decimal odds to net odds before applying a probability-based stake model.','It connects price, estimated edge and bankroll exposure.','f=(p D−1)/(D−1), with p estimated independently and D the net-of-cost-equivalent price.','A more attractive payout can lower the chance needed for a positive modeled edge.'],[['p=55%, D=2.00. Full and half Kelly?','10% and 5% of bankroll.'],['If p comes from fitting only past winning bets, what is the sizing problem?','Selection biases p upward and can lead to severe overbetting.'],['p=40%, D=3.00, quarter Kelly on €2,000?','Full Kelly 10%; quarter 2.5%; stake €50.'],['Why must settlement rules be checked?','Voids, pushes, commissions and partial payouts change the outcomes used in the formula.'],['At D=1.80 and p=55%, what does a no-short Kelly model choose?','Zero. p D−1=−0.01 is negative before extra costs.'],['Why shouldn’t the largest point-estimate Kelly always be chosen among many searched bets?','Searching many noisy estimates selects exaggerated edges; account for selection and joint exposure.']],'f=(p D−1)/(D−1)',[['.25*.1*2000',50]]);
r(4,'applications','closing-line','Closing-line value',['A comparison of the price taken with a later market closing price under the same contract.','It can assess whether entry prices beat a benchmark without relying only on outcomes.','Use comparable markets and settlements; a better price is a signal, not proof of true edge.','Buying the same ticket cheaper than its later price can be evidence of timing skill.'],[['You take decimal 2.20; market closes 2.00. Better payout at entry?','Yes. 2.20/2.00−1=10% more total payout per winning stake.'],['Does beating the closing price guarantee this bet wins?','No. It concerns price, not certainty of outcome.'],['Why compare no-vig closing probabilities rather than one raw price alone?','The market margin and allocation can change, distorting a simple price comparison.'],['What makes a CLV comparison invalid?','Different rules, timing, lines, liquidity or selectively recording only favorable moves.'],['If closing fair chance is 50%, what EV does 2.20 imply per €1?','0.5×2.2−1=+€0.10, if that closing probability is a sound benchmark.'],['Why might persistent positive CLV still need investigation?','Thin quotes, unavailable execution and an inefficient benchmark can create apparent value.']],'benchmark EV = p_close × D_taken−1',[['.5*2.2-1',.1]]);
r(4,'applications','fill-risk','Execution risk versus trigger rules',['An order trigger determines when it activates; actual fills determine realized money outcomes.','It prevents a nominal stop from being treated as a guaranteed maximum loss.','Model realistic fills, gaps, spread and liquidity separately from the trigger.','An alarm tells you to leave; it does not guarantee the exit door is clear.'],[['Buy €10; stop trigger €9.50; actual sell €9.00. Realized price loss?','€1/share, or 10%, rather than the planned 5%.'],['A triggered stop-market order promises which price?','No fixed execution price; it seeks execution at available prices after activation.'],['How does a stop-limit change the tradeoff?','It limits the permitted execution price but may fail to exit.'],['What evidence supports a fill-risk estimate?','Representative order and trade data including stressed, halted or illiquid periods.'],['At 200 shares, a €0.50 extra exit loss costs what?','€100 extra.'],['Why can two strategies with the same planned stop have different tail loss?','Different instruments, size, leverage and liquidity can produce very different actual exits.']],'realized loss = size × (entry−actual exit)',[['200*.5',100]]);
r(4,'applications','return-volatility','Volatility and return units',['Dispersion of returns, usually summarized by their standard deviation.','It describes uncertainty around returns rather than the direction of expected profit.','Use comparable return units and sampling intervals; distinguish standard deviation from variance.','A rough path has bigger bumps even if it ends at the same destination.'],[['Daily volatility is 2%. What units does its variance have?','Squared return units; decimal variance is 0.02²=0.0004.'],['Does 2% daily volatility mean a hard 2% maximum loss?','No. Standard deviation is a spread measure, not a loss ceiling.'],['Two equal mean-return strategies have SD s 1% and 3%. Which is more dispersed?','The 3% SD strategy, with three times the SD and nine times the variance.'],['Before using normal-based probabilities, what distribution issues matter?','Fat tails, skewness, dependence and changing volatility.'],['At €10,000 exposure, a 2% return move is how much money?','€200; this is an illustrative scale, not a guaranteed range.'],['Why does volatility miss some important investment risks?','Illiquidity, leverage, permanent impairment and asymmetric tail losses are not fully described by SD.']],'variance = SD²',[['.02**2',.0004]]);
// Intermediate.
r(5,'arithmetic','pooled-rates','Pooling rates with unequal groups',['Combine events and denominators before calculating an overall rate.','It avoids misleading averages of conversion or success percentages.','Pooled rate = total events/total eligible exposures.','Each visitor is one vote; small and large groups should not get equal votes.'],[['Group A has 1/10 buyers, B 90/100. Pooled conversion?','91/110≈82.73%.'],['Why is averaging 10% and 90% wrong here?','It gives a group of 10 the same weight as a group of 100.'],['When is an unweighted average of group rates appropriate?','When the estimand intentionally gives equal weight to groups, not to individuals.'],['What must be checked before pooling?','Definitions, exposure periods, missing data and whether groups represent the same target.'],['Two periods have 20/100 and 60/300 successes. Overall rate?','80/400=20%.'],['Can a pooled improvement happen even if every subgroup worsens?','Yes. Changing subgroup weights can reverse the overall trend; examine subgroup rates and composition.']],'pooled rate = Σ successes/Σ denominators',[['91/110*100',82.72727272727273]]);
r(5,'arithmetic','simple-vs-compound','Simple versus compound growth',['Simple growth uses the original base; compound growth uses the changing base.','It checks whether an interest or performance claim matches the actual reinvestment rule.','Simple factor=1+nr; compound factor=(1+r)^n.','Simple growth adds equal blocks; compounding grows the blocks themselves.'],[['€100 at 10% for three years: simple versus compounded?','€130 versus €133.10.'],['Can you add yearly returns when gains are reinvested?','Not for exact total growth; multiply the yearly factors.'],['At zero rate, how do simple and compound amounts compare?','They are equal to the starting amount.'],['What contract detail determines the right method?','Whether and when interest is reinvested or paid out, plus fees and day-count conventions.'],['At 5% for two years, what extra does compounding earn per €100?','€110.25−€110=€0.25.'],['Why can a “10% yearly cash yield” differ from a 10% compound return?','Cash payouts may not be reinvested at the same rate, and asset value can change.']],'simple=V(1+nr); compound=V(1+r)^n',[['100*1.1**3',133.1]]);
r(5,'arithmetic','continuous-growth','Continuous compounding',['A model where growth accumulates continuously at a constant instantaneous rate.','It connects exponential growth, log returns and calculus.','V(t)=V 0 e^(rt); r=ln(V(t)/V 0)/t.','Growth keeps building without waiting for a yearly posting date.'],[['Continuous rate r=0.05 for one year. Simple annual return?','e^0.05−1≈5.127%.'],['Is a 5% continuous rate identical to a 5% annual effective rate?','No; effective annual growth is about 5.127%.'],['What continuous rate gives 10% effective annual growth?','ln1.1≈9.531%.'],['What assumption does the exponential model make?','The instantaneous rate remains constant and the base is positive.'],['Continuous doubling time at r=0.10?','ln 2/0.10≈6.93 years.'],['Can an exponential growth fit remain valid indefinitely for an app?','Usually capacity, saturation or changing demand breaks the constant-rate assumption; use it within a justified range.']],'V(t)=V0e^(rt)',[['Math.exp(.05)-1',.05127109637602412]]);
r(5,'arithmetic','cost-basis-points','Costs in basis points',['Small proportional charges expressed as hundredths of a percentage point.','It makes narrow trading edges and fees easier to compare.','Cost cash=notional×basis points/10,000; distinguish per-side from round-trip cost.','A few drops matter when the bucket’s expected surplus is tiny.'],[['A 12-basis-point fee on €10,000 costs what?','€12; 12 bp=0.12%.'],['Does a 5-bp entry fee plus 5-bp exit fee mean 5-bp round trip?','No. Approximately 10 bp if both use comparable notionals.'],['An edge of 8 bp faces 11 bp costs. Net edge?','−3 bp, or −0.03%, under an additive small-return approximation.'],['What can prevent simple addition of quoted cost percentages?','Different bases, timing, minimum fees, currency conversion and market impact.'],['Trading €50,000 at 4 bp costs how much on that side?','€20.'],['Why can lower commissions still produce worse all-in execution?','Spread, slippage and missed fills may exceed the commission saving.']],'cash cost = notional × bp/10000',[['50000*4/10000',20]]);
r(5,'arithmetic','cost-adjusted-hurdle','Cost-adjusted break-even growth',['The gross growth needed to cover proportional or fixed costs.','It prevents a positive price return from being mistaken for net profit.','Solve final net proceeds = total starting cost; model each cost on its actual base.','A runner must cross the starting fee hurdle before a price gain becomes profit.'],[['Buy €100 with a €2 fee and sell with a €2 fee. Price proceeds needed to break even?','€104, so price must rise 4% from €100.'],['Is adding 2%+2% always the exact round-trip hurdle?','No. Percentage fees may apply to different bases; fixed fees behave differently.'],['Buy-side charge 1%; sell-side deduction 1%. Exact gross factor needed?','1.01/0.99≈1.020202, or 2.0202% growth.'],['Which prices should be used for a hurdle estimate?','Realistic executable entry/exit prices with every applicable cost.'],['A €200 purchase has total fixed fees €6. Price gain needed?','€6/€200=3%.'],['An estimated 2% gross edge faces a 2.02% exact hurdle. What does that imply?','The modeled net edge is slightly negative, before extra execution uncertainty.']],'required factor = (1+entry fee)/(1−exit fee)',[['1.01/.99-1',.02020202020202011]]);
r(5,'decisions','ruin','Risk of ruin',['The chance that capital falls below a threshold where continuing is impossible or unacceptable.','It considers survival, not only average profit.','Define the ruin threshold and full loss process; EV alone cannot determine ruin probability.','A profitable engine is useless after it runs out of fuel.'],[['Bankroll €100, fixed stake €20. Five straight full losses leave what?','€0: ruin at that sequence.'],['Does positive EV imply zero ruin chance?','No. Losing sequences, large stakes and tail events can exhaust capital.'],['If the ruin threshold is €50 rather than zero, is the risk definition unchanged?','No. You are measuring crossing a different boundary.'],['What inputs are needed to estimate ruin?','Payoff distribution, sizing rule, dependence, horizon and starting capital.'],['At independent 50% loss chance, probability of five immediate losses?','0.5⁵=3.125%. This is one ruin path, not total eventual ruin probability.'],['Why can fractional sizing avoid exact zero in an ideal model yet still be unsafe?','Capital can fall below a practical threshold, and gaps or obligations can violate the bounded-loss model.']],'ruin = P(wealth crosses defined threshold)',[['.5**5*100',3.125]]);
r(5,'decisions','log-growth','Expected logarithmic growth',['Average log of the wealth multiplier, the objective behind Kelly sizing.','It accounts for how repeated losses and gains compound.','Binary growth g(f)=p ln(1+bf)+(1−p)ln(1−f), for feasible positive factors.','A +50% then −50% sequence averages 0% simple return but loses a quarter of wealth.'],[['Even money, p=60%, f=20%. Model expected log growth per bet?','0.6 ln 1.2+0.4 ln 0.8≈0.02014, or 2.014% in log units.'],['Can ln of expected wealth replace expected ln wealth?','No. Averaging and taking a logarithm are different operations.'],['For f=0, what is expected log growth?','0: the modeled bankroll stays unchanged.'],['Why must 1−f remain positive in this binary model?','A zero or negative wealth factor makes finite log growth invalid.'],['At p=50%, f=20%, is expected log growth positive?','No. 0.5 ln 1.2+0.5 ln 0.8=0.5 ln 0.96≈−0.02041.'],['What distinguishes money EV from log growth here?','Money EV is linear in stake; log growth penalizes large fractional losses and can peak at an interior fraction.']],'g(f)=p ln(1+bf)+q ln(1−f)',[['.6*Math.log(1.2)+.4*Math.log(.8)',.020135513550688863]]);
r(5,'decisions','overbetting','Overbetting relative to Kelly',['Staking more than the model’s growth-optimal fraction.','It shows why more exposure is not always better despite positive money EV.','Compare expected log growth at candidate fractions, allowing for uncertain probabilities.','Pressing the accelerator beyond grip can reduce useful speed.'],[['p=60%, even money. Is f=40% above full Kelly?','Yes. Full Kelly is 20%; 40% is twice it.'],['“Twice Kelly means twice the long-run growth.” Why wrong?','Expected log growth is curved, not linear in stake; too much exposure can reduce growth below zero.'],['At f=40%, p=60%, expected log growth sign?','Negative: 0.6 ln 1.4+0.4 ln 0.6≈−0.00245.'],['Which estimate matters when labeling a stake overbetting?','The true model parameters; an estimated optimum can itself be too large.'],['If estimated full Kelly is 20% but the credible optimum might be 4%, what does half estimated Kelly do?','It stakes 10%, still above the 4% optimum. Fractional Kelly does not remove input error.'],['Why is position size a decision separate from detecting a positive edge?','An edge can exist while excessive size gives unacceptable risk or negative compound growth.']],'growth(f) need not rise with f',[['.6*Math.log(1.4)+.4*Math.log(.6)',-.0024469075336686075]]);
r(5,'decisions','dynamic-sizing','Fractional sizing and path effects',['Recompute stakes as a share of changing bankroll.','It models compounding and distinguishes fixed-cash from fixed-fraction risk.','After a return, update wealth, then apply the same fraction to the new base.','The next slice grows or shrinks with the pie.'],[['Start €1,000; win an even-money 10% stake, then lose a 10% stake. End wealth?','€1,000×1.1×0.9=€990.'],['Why do equal fractional win and loss not cancel?','They act on different bankrolls. The second loss is larger after the first gain.'],['With fixed €100 win then €100 loss, ending wealth?','€1,000, assuming both stakes remain feasible.'],['What changes the equivalence of return order?','Cash flows, stake constraints, path-dependent stops or strategy changes.'],['Two 10% losses leave what fraction of capital?','0.9²=81%, a 19% drawdown.'],['Why can fixed stakes become dangerous during a drawdown?','The same cash stake represents an increasing fraction of the shrinking bankroll.']],'wealth multiplier = Π(1+fractional outcome)',[['1000*1.1*.9',990]]);
r(5,'decisions','correlated-kelly','Related bets and Kelly',['Bets whose outcomes or estimation errors move together.','It avoids summing single-bet fractions as though risks were isolated.','Optimize or constrain the joint wealth outcomes, not each marginal bet separately.','Ten umbrellas on the same rainy day are ten copies of one weather exposure.'],[['Two identical even-money bets each risk 10% on the same event. Total event risk?','20% of bankroll, not two independent 10% risks.'],['Does multiplying two loss probabilities work for perfectly related bets?','No. Their joint loss chance equals the single-event loss chance.'],['At 40% loss chance, compare independent and identical two-bet joint loss chances.','Independent:16%; identical:40%.'],['What dependence needs checking besides realized outcome correlation?','Shared model errors, common market shocks and linked liquidity needs.'],['You have three 5% positions all hurt by one announcement. Simultaneous full stake loss?','15% of bankroll, if each loss is limited to its stake.'],['Why can diversification estimated in calm data fail under stress?','Dependence can strengthen during the event that matters, and liquidity can deteriorate together.']],'joint exposure uses joint distribution',[['.4*.4*100',16]]);
r(5,'applications','sharpe-sortino','Sharpe and downside risk',['Risk-adjusted return measures using different definitions of variability.','They compare reward with return dispersion, while leaving other risks to inspect.','Sharpe=(mean return−risk-free return)/SD; Sortino uses downside deviation from a specified target.','Two vehicles reach similar speed, but one has more bumps or worse downward shocks.'],[['Annual return 12%, risk-free 2%, annual SD 20%. Sharpe?','(12−2)/20=0.5.'],['Does Sharpe 2 guarantee small drawdowns?','No. Tail risk, leverage, illiquidity and estimation error can be hidden by a single ratio.'],['What changes between Sharpe and Sortino?','The denominator: all-return SD versus downside deviation relative to a defined target.'],['What must align in a Sharpe calculation?','Return, risk-free rate and SD horizon, units and data treatment.'],['Two annual Sharpe numerators 8% and SD s 10%,20%. Ratios?','0.8 and 0.4. Same excess return, twice the SD halves the ratio.'],['Why can a smooth illiquid asset have misleadingly high Sharpe?','Stale or smoothed valuations can understate measured volatility; executable losses may be larger.']],'Sharpe=(μ−r_f)/σ',[['(12-2)/20',.5]]);
r(5,'applications','max-drawdown','Maximum drawdown',['The largest observed peak-to-trough wealth decline in a specified record.','It summarizes a severe path loss and the recovery burden.','At each time, compare wealth with its earlier running peak; take the largest percentage fall.','Measure the deepest valley below any hilltop already reached.'],[['Wealth path 100→120→90→110. Maximum drawdown?','(120−90)/120=25%.'],['Is maximum drawdown the loss from the very first value only?','No. It uses prior peaks; the 90 value is 25% below the 120 peak.'],['What recovery gain repairs this 25% drawdown?','25/75=33.33%.'],['What does a historical maximum drawdown not establish?','A future loss limit; unseen events and changed exposures can be worse.'],['Wealth 100→80→130→100. Maximum drawdown?','max(20%,30/130)=23.08%.'],['Why must strategy comparisons use matching samples and assumptions?','Longer records or different leverage, costs and cash flows can change observed maximum drawdown.']],'DD_t=1−W_t/max_{s≤t}(W_s)',[['30/130*100',300/13]]);
r(5,'applications','turnover-hurdle','Turnover and cost drag',['Repeated transactions consume part of gross strategy returns.','It evaluates whether a small edge survives frequent trading.','Estimate total realistic turnover costs, without assuming constant spreads at larger size.','A tiny leak per trip can drain the tank when you make many trips.'],[['Each of 100 equal €1,000 round trips costs 0.1%. Total cash cost?','100×€1,000×0.001=€100.'],['Is a 0.1% cost negligible regardless of frequency?','No. Frequency and notional determine total cash drag.'],['An average gross edge of 6 bp meets 8 bp all-in costs. Net per-turnover edge?','−2 bp.'],['What costs should a turnover analysis include?','Spread, commissions, adverse fills, market impact and relevant financing.'],['Gross profit €300 minus €100 transaction costs gives what reduction in profit?','Net €200; costs reduce gross profit by 33.33%.'],['Why can a slower strategy outperform a higher gross-return strategy?','Lower turnover, costs and impact can leave a higher net return despite lower gross performance.']],'net return depends on cost × turnover',[['100*1000*.001',100]]);
// Strong intermediate.
r(6,'arithmetic','annualizing-return','Annualizing a period return',['Express a period’s growth as an equivalent yearly rate under repetition assumptions.','It compares horizons while exposing how fragile short-run extrapolation can be.','Annual factor=(1+r_period)^(periods/year); subtract one.','Repeating one fast lap for an entire race is an assumption, not an observation.'],[['A 1% monthly compound return repeats for 12 months. Annual rate?','1.01¹²−1≈12.68%.'],['Does a 20% return in one week prove a huge annual return is achievable?','No. The same opportunity and rate may not persist, and the extrapolation can be extreme.'],['A 10% six-month return repeated twice gives what annual rate?','1.1²−1=21%.'],['What must be stated with an annualized return?','Observed horizon, extrapolation rule, reinvestment, costs and whether cash flows are included.'],['A −5% monthly return repeated 12 times gives what annual result?','0.95¹²−1≈−45.96%.'],['Why compare actual multi-year net performance as well as annualized short samples?','Short samples can be dominated by luck and fail to represent the repeatable process.']],'r_annual=(1+r_period)^m−1',[['1.01**12-1',.12682503013196977]]);
r(6,'arithmetic','sqrt-time','Square-root time volatility scaling',['Under independent identically distributed finite-variance returns, summed-return SD grows with √time.','It explains a common annualization approximation and its limitations.','Variance of independent sums adds; SD is the square root of variance.','Random steps partly cancel, unlike walking steadily in one direction.'],[['Daily SD is 1%, with 252 independent equal-variance days. Approximate annual SD?','1%×√252≈15.87%.'],['Why not multiply daily SD by 252?','Independent variance adds; SD grows with √252, not 252.'],['Four independent periods have what SD relative to one?','Twice the SD, since √4=2.'],['What can invalidate √time scaling?','Autocorrelation, changing volatility, heavy tails with no finite variance, or the approximation to compounded returns.'],['Daily SD 2%, over 25 independent days. Sum-return SD?','2%×5=10%.'],['Would serially positive-correlated daily returns generally have the same variance as the independence calculation?','No. Positive covariance terms increase summed variance.']],'σ_T≈σ_1√T under stated assumptions',[['Math.sqrt(252)',15.874507866387544]]);
r(6,'arithmetic','leverage','Leverage and capital returns',['Exposure larger than the equity used to support it.','It magnifies both asset moves and the effect of financing and margin constraints.','Ignoring costs, equity return≈exposure/equity × asset return.','A longer lever moves your end farther in both directions.'],[['€5,000 exposure on €1,000 equity. Asset falls 4%. Equity price loss?','€200, or 20% of equity.'],['Does five-times leverage multiply profit without multiplying loss?','No. It amplifies adverse moves too and can force liquidation.'],['At 5× exposure, a 10% asset fall costs what fraction of initial equity before costs?','50%.'],['What must a leverage scenario include?','Financing, margin rules, fill risk, changing exposure and possible losses beyond posted equity.'],['Asset rises 2% at 3× leverage. Approximate equity return before costs?','+6%.'],['Why can a leveraged strategy fail despite later price recovery?','A margin call or liquidation can remove the position before recovery occurs.']],'equity return≈L×asset return',[['5000*.04/1000*100',20]]);
r(6,'arithmetic','return-contributions','Portfolio return contributions',['Each position’s starting weight multiplied by its same-period return.','It identifies which holdings drive portfolio profit or loss.','Contribution_i=weight_i×return_i; sum contributions for the portfolio before flows/costs.','A small engine moving fast may contribute less than a large engine moving moderately.'],[['40% weight earns 10%; 60% earns −5%. Portfolio return?','4%−3%=+1%.'],['Is the 40%-weight asset’s contribution 10 percentage points?','No. Its contribution is 4 percentage points of portfolio return.'],['A 10%-weight asset returns 100%. Contribution?','10 percentage points.'],['What weights are used for simple period attribution?','Starting weights, with cash flows and rebalancing handled consistently.'],['A 50/50 portfolio gets +20% and −10%. Return?','+5%.'],['Why can attribution differ for a portfolio rebalanced during the period?','Weights change; a single starting-weight calculation may not capture all trading and cash-flow effects.']],'R_portfolio=Σw_i r_i',[['.4*.1+.6*(-.05)',.01]]);
r(6,'arithmetic','growth-decomposition','Multiplicative business growth',['Revenue growth from multiplying changes in customers and revenue per customer.','It separates volume growth from monetization changes.','Revenue factor=customer factor×revenue-per-customer factor, if definitions align.','More customers and fuller baskets multiply together.'],[['Customers rise 20%, average revenue/customer rises 10%. Revenue growth?','1.2×1.1−1=32%.'],['Why is adding 20%+10%=30% incomplete?','It omits the 2% interaction: the extra customers also earn the higher average.'],['Customers fall 10% but revenue/customer rises 20%. Revenue change?','0.9×1.2−1=+8%.'],['What must be checked before using this decomposition?','Consistent periods, customer definitions and whether revenue/customer includes the same customers.'],['Revenue rises 50% while customers rise 25%. Average revenue/customer change?','1.5/1.25−1=20%.'],['Can a rise in average revenue/customer indicate every customer spent more?','No. The mix may shift toward high-spending customers.']],'revenue=customers×revenue/customer',[['1.5/1.25-1',.2]]);
r(6,'decisions','posterior-edge','Averaging uncertain edges',['Combine possible probability values using their evidence-based weights.','It avoids sizing from the most optimistic plausible estimate alone.','For linear money EV, use the probability-weighted average p under the uncertainty model.','A forecast range is a basket of plausible worlds, not a menu to choose the nicest one.'],[['p is 50% or 70%, equally plausible. Average p and even-money expected ROI?','p=60%; ROI=2 p−1=20%.'],['Why not use 70% simply because it is possible?','That ignores the equally plausible weaker case and overstates the expected edge.'],['If 70% p has 25% weight and 50% p has 75%, average p?','55%.'],['What makes the uncertainty weights defensible?','Transparent evidence, model assumptions and calibration rather than wishful weighting.'],['With average p=55% and D=1.80, expected ROI?','0.55×1.8−1=−1%.'],['Does averaging p remove concern about persistent model error across repeated bets?','No. A shared unknown p can correlate outcomes and leave uncertainty about long-run profitability.']],'E[ROI]=D E[p]−1',[['.25*.7+.75*.5',.55]]);
r(6,'decisions','robust-sizing','Sizing with probability uncertainty',['Choose exposure that remains tolerable when the estimated edge is wrong.','It connects stake size with model sensitivity and loss constraints.','Examine a credible probability range or posterior and joint loss scenarios; fractional sizing is one option, not a guarantee.','Build a bridge for a heavier load than the average estimate.'],[['Even money: estimated p 60%, but a credible low case is 52%. Compare full Kelly fractions.','20% versus 4%; sizing is very sensitive to the probability estimate.'],['Does using the low-case fraction prove safety?','No. The low case can still be wrong, and losses can cluster.'],['At p 50% even money, what is full Kelly?','0%, showing how a smaller edge estimate can eliminate a stake.'],['What additional constraints can override a growth-optimal fraction?','Liquidity, reserve needs, maximum tolerable drawdown and correlated commitments.'],['Bankroll €1,000; estimated Kelly 20%; half of low-case Kelly 4%. Stake?','2% of bankroll=€20.'],['Why should uncertainty increase when entering a new market?','Past calibration may not transfer; the relationship between signals and outcomes can change.']],'stress f(p) across credible p values',[['.5*.04*1000',20]]);
r(6,'decisions','sample-information','Imperfect information value',['Expected action improvement after receiving an imperfect signal.','It decides whether a test is worth buying without assuming it is flawless.','Average optimized conditional decisions over possible signals, then subtract the no-signal value and test costs.','A cloudy weather report can still help, but it cannot act like a crystal ball.'],[['Without a test best EV €20; with it, best action averages €28. Test costs €6. Net gain?','€2.'],['Can using a test’s favorable result while ignoring unfavorable results estimate test value?','No. Average over every signal outcome, including the cases where the action changes unfavorably.'],['Perfect information is worth €15. An imperfect test claims €25 under the same model. Concern?','The calculation is inconsistent; imperfect information cannot exceed the perfect-information bound.'],['What probability does a signal-based decision need?','The posterior state probability conditional on that signal, not sensitivity alone.'],['Signal A occurs 40% with optimized value €50; B occurs 60% with value €10. Expected optimized value?','0.4×€50+0.6×€10=€26.'],['Why can a test with high classification accuracy have low business value?','Errors may concern low-value cases, or its signals may not change the preferred action.']],'EVSI=E_signal[max_a E(payoff|signal)]−baseline',[['.4*50+.6*10',26]]);
r(6,'decisions','decision-threshold','Probability threshold for action',['The probability at which two available actions have equal expected value.','It links forecasts to concrete business or trading choices.','Set the competing payoff equations equal and solve, including costs and alternatives.','A thermometer reading matters because it crosses an action threshold.'],[['An action pays +€90 if successful and −€30 otherwise; skipping pays zero. Threshold p?','30/(90+30)=25%.'],['Should a forecast above 50% always trigger action?','No. The relevant threshold depends on payoffs, costs and alternatives.'],['If the action also costs €6 every time, new threshold?','(30+6)/120=30%.'],['Why should an action threshold be reassessed when costs change?','A forecast can stay the same while the best decision changes because net payoffs change.'],['A safe alternative pays €12. Original action EV is 120 p−30. Threshold against that alternative?','120 p−30=12; p=35%.'],['What should happen when p’s uncertainty straddles the threshold?','Recognize that the recommendation is fragile; assess further information, exposure or a robust alternative.']],'choose action if EV_action > EV_alternative',[['42/120*100',35]]);
r(6,'decisions','option-to-wait','Value of waiting',['Delay can preserve flexibility but also lose an opportunity.','It compares learning and optionality with delay costs.','Include future information, expiration, discounting and lost cash flows in the decision tree.','Waiting to cross a road gives more information, but waiting forever misses the bus.'],[['Waiting improves expected payoff by €12 but loses €8 revenue. Net benefit?','€4, before other delay costs.'],['Is waiting always better because information increases?','No. Opportunities can disappear and costs or competition can grow.'],['What differs between a reversible and irreversible choice?','An irreversible choice loses more flexibility; later information may be more valuable before committing.'],['What must be checked in an option-to-wait calculation?','Whether future actions are truly available and the information arrives before the deadline.'],['An immediate offer yields €100; a delayed expected €110 is discounted by factor 0.9. Which cash EV is higher now?','Immediate: €100 versus €99 present value.'],['Why can a small pilot outperform committing full capital now?','It can reveal demand while limiting loss, provided the pilot is informative and scaling remains feasible.']],'net delay value = information/option gain − delay cost',[['110*.9',99]]);
r(6,'applications','diversification','Covariance and diversification',['Combining exposures whose returns do not move identically.','It can reduce portfolio variance without assuming each position is low risk.','For two assets, variance=w 1²σ1²+w 2²σ2²+2 w 1 w 2 Cov.','Two boats rocking differently can make the combined deck steadier.'],[['Equal weights, equal 10% SD, zero correlation. Portfolio SD?','10%/√2≈7.07%.'],['Does owning two ticker symbols ensure diversification?','No. They may share the same risk drivers and losses.'],['With correlation 1 in that equal-SD example, portfolio SD?','10%; perfect co-movement removes the variance reduction.'],['What assumptions need stress testing?','Correlation stability, volatility estimates, liquidity and simultaneous tail shocks.'],['With correlation−1, equal weights and equal SD, modeled variance?','Zero in the ideal linear two-asset model; real hedges have mismatch and costs.'],['Why can zero historical correlation fail to protect against a crash?','Ordinary correlation can miss shared tail dependence and may change during stress.']],'Var(portfolio)=Σ_iΣ_j w_i w_j Cov(i,j)',[['.1/Math.sqrt(2)',.07071067811865475]]);
r(6,'applications','var','Value at Risk',['A loss quantile for a stated horizon and model.','It sets a probabilistic loss threshold but does not describe how severe worse losses can be.','Va R at level α is an α-quantile of loss; it is not the maximum possible loss.','Mark a line near the deep end; it does not tell you how deep the pool continues.'],[['A continuous loss model has 95% Va R €100. What does that mean?','About 95% of modeled losses are at or below €100; roughly 5% exceed it, for the stated horizon.'],['Does 95% Va R €100 mean you cannot lose more than €100?','No. Tail losses can be much larger.'],['What differs between 95% and 99% Va R?','Different quantiles: the higher confidence level typically gives a higher loss threshold.'],['Which details are essential beside a Va R number?','Horizon, portfolio, model, confidence level, sample quality and changing conditions.'],['Two portfolios have equal 95% Va R but tail losses €200 versus €2,000. Equal tail risk?','No. Va R alone cannot distinguish the magnitude beyond the cutoff.'],['Why can historical Va R miss an unseen crisis?','The sample may not contain the relevant shock, and present exposures or liquidity can differ.']],'Va R_α = loss quantile at α');
r(6,'applications','expected-shortfall','Expected shortfall',['The average loss within the worst specified tail fraction.','It adds tail-loss severity to a quantile threshold.','ES at level α averages the worst 1−α share of loss probability, with proper weighting for discrete outcomes.','Instead of noting where the deepest water starts, measure average depth in that end of the pool.'],[['The worst 10% of equally weighted cases are losses €100 and €300. Their tail average?','€200.'],['Does ES equal Va R in every distribution?','No. ES accounts for losses within the tail; Va R is a quantile.'],['If those worst two losses become €100 and €900, how does ES change?','€200→€500, a 150% increase.'],['Why is “average losses strictly above Va R” tricky with tied discrete losses?','It may not include exactly the required tail probability. Weight boundary losses to fill the worst tail fraction.'],['A 95% tail consists of 4% probability of €100 loss and 1% of €600. ES 95?','(0.04×100+0.01×600)/0.05=€200.'],['Can accurate estimated ES remove model and liquidity risk?','No. Tail probabilities and stressed liquidation losses can be misspecified.']],'ES_α = average worst (1−α) probability mass',[['(.04*100+.01*600)/.05',200]]);
r(6,'applications','poker-ranges','Poker range combinations',['A probability-weighted set of possible hands rather than one guessed hand.','It combines card removal, action patterns and equity into a decision model.','Weight each feasible holding, account for blockers, then average payoff or equity over the range.','Do not assign the opponent one face-down card pair; imagine a weighted stack of possible pairs.'],[['A range is 60% hands against which you have 80% equity and 40% hands against which you have 20%. Average equity?','0.6×0.8+0.4×0.2=56%.'],['Why is averaging the two equity values to 50% wrong?','The groups have unequal probability weights.'],['How many distinct unordered pairs can be chosen from four available cards?','4×3/2=6.'],['Why must blockers be considered?','Visible and held cards remove possible opponent combinations and change range weights.'],['A range has 20 value combinations and ten bluff combinations with equal per-combo weight. Bluff share?','10/30=33.33%.'],['Why can action frequency invalidate simple combination counting?','Different holdings may bet at different rates, so posterior range weights are not all equal.']],'range equity = Σ weight(hand) × equity(hand)',[['.6*.8+.4*.2',.56]]);
// Early advanced: sensitivity, constraints and correlated risk.
r(7,'arithmetic','elasticity','Elasticity',['A proportional response relative to a proportional input change.','It compares price sensitivity and demand across different scales.','Local elasticity=(dy/dx)×(x/y); a finite percent-change ratio is an approximation over a range.','A 1% push on one lever may move the output by 2%.'],[['A small 1% price rise causes approximately a 2% quantity fall. Demand elasticity?','Approximately −2.'],['Does elasticity −2 mean quantity falls two units for each €1 rise?','No. Elasticity uses percentage changes; slope uses original units.'],['Price rises 5%, quantity falls 10%. Approximate elasticity?','−10%/5%=−2.'],['What should be checked before extrapolating a local elasticity?','Whether the response stays similar over the proposed range and whether the estimate is causal.'],['With constant elasticity −1, a 10% price rise changes quantity by what exact factor?','Quantity factor=1.1^−1≈0.9091, a 9.09% fall; revenue is unchanged in that model.'],['Why can observational price/quantity data give a misleading elasticity?','Demand shifts, promotions and seasonality can move both variables, confounding the price effect.']],'elasticity=(dy/dx)(x/y)',[['1/1.1-1',-1/11]]);
r(7,'arithmetic','small-return-approx','Small-return approximations',['Simplified growth arithmetic useful when omitted terms are negligible.','It speeds mental checks while making approximation error explicit.','ln(1+r)≈r for small r; multiplying (1+a)(1+b) adds an interaction ab.','Straightening a tiny bend is useful; straightening a sharp turn loses the path.'],[['What term is omitted when approximating two +1% returns as +2%?','0.01×0.01=0.0001, or 0.01 percentage point. Exact return is 2.01%.'],['Why is adding +50% and −50% a poor compounding approximation?','The interaction is −25 percentage points, too large to ignore.'],['At +5% and +2%, exact total return?','1.05×1.02−1=7.1%, versus the 7% additive approximation.'],['When is an approximation unacceptable?','When its error can change the decision, especially near a narrow break-even threshold.'],['ln 1.01 is approximately what, and how does it compare with 0.01?','About 0.00995; slightly smaller than 0.01.'],['A claimed edge is 0.005 percentage point but omitted compounding terms are 0.01 point. Can the shortcut establish the edge?','No. Approximation error is larger than the claimed advantage.']],'(1+a)(1+b)−1=a+b+ab',[['1.05*1.02-1',.071]]);
r(7,'arithmetic','fee-compounding','Recurring fee drag',['Repeated proportional fees reduce growth by repeatedly shrinking wealth.','It evaluates long-term net performance rather than subtracting one fee once.','With a fee on end-period wealth, net factor=(1+gross return)(1−fee); repeat consistently.','A small leak each year also removes future growth on the lost money.'],[['Gross annual return 10%, annual fee 1% on end-year wealth. Net annual rate?','1.1×0.99−1=8.9%.'],['Why is 10%−1%=9% not exact under that fee timing?','The fee also charges the year’s gain; the interaction removes another 0.1 percentage point.'],['At zero gross growth, five annual 2% wealth fees leave what fraction?','0.98⁵≈90.39%.'],['What contract detail matters for fee arithmetic?','Fee base, timing, performance fees, minimum charges and cash flows.'],['Two otherwise identical portfolios differ only by a 1% yearly wealth fee for 10 years. Fee-only wealth ratio?','0.99¹⁰≈90.44%; about 9.56% less wealth.'],['Why should a gross-return comparison also report net-of-fee terminal wealth?','Small recurring costs accumulate and reduce the capital that earns later returns.']],'wealth fee ratio=(1−f)^n',[['.99**10',.9043820750088044]]);
r(7,'arithmetic','precision','Precision versus accuracy',['More decimal places describe numerical resolution, not how true the inputs are.','It prevents exact-looking forecasts from hiding large model error.','Round outputs sensibly and report input uncertainty; keep enough digits for threshold calculations.','A ruler marked in micrometers cannot fix an uncertain place to start measuring.'],[['A model reports p=55.123456% from 20 trials. Does that establish six-decimal accuracy?','No. Sampling and model uncertainty overwhelm those extra digits.'],['Why is a perfectly calculated EV not necessarily accurate?','Its probability and payoff inputs may be wrong.'],['A return estimate is 5%±3 percentage points. Is rounding it to 5.0000% useful?','No. The important uncertainty is about 2%–8%, not tiny decimal variation.'],['When should full internal precision be kept?','During calculations near a threshold; round only the displayed result after checking sensitivity.'],['A threshold is 33.333…%; an estimate 33.32% is displayed 33.3%. Is it above threshold?','No. The rounded display hides a small negative gap.'],['What is a better report than “profit will be€123.456”?','A stated expected amount with scenarios or an uncertainty range and the assumptions behind it.']],'numerical precision ≠ estimate accuracy');
r(7,'arithmetic','odds-formats','Converting odds formats',['Different notations for the same stake and net winning payoff.','It allows consistent EV calculations across betting markets.','Fractional a/b gives D=1+a/b; American +A gives D=1+A/100; −A gives D=1+100/A for positive A.','Different labels can describe the same ticket price.'],[['Fractional 3/1 equals what decimal odds and implied chance?','D=4.00; implied chance 25%.'],['Why is fractional 3/1 not decimal 3.00?','The 3 is profit per unit; decimal odds also include the returned stake.'],['American−150 implies what chance?','150/(150+100)=60%; decimal 1.6667.'],['What settlement assumption underlies these conversions?','A standard full-win/full-loss contract, excluding pushes and extra charges.'],['American+200 means what profit on a€10 winning stake?','€20 profit, €30 total return; implied chance 33.33%.'],['Do equivalent odds formats imply the same net EV after different fees?','No. Convert the payoffs and subtract each market’s actual costs before comparing.']],'D=1+fractional profit ratio',[['150/(150+100)*100',60]]);
r(7,'decisions','multioutcome-kelly','Kelly with more than two outcomes',['Choose a stake using every possible net return, including partial wins, losses or voids.','It avoids applying binary Kelly to a contract with different outcomes.','Maximize Σp_i ln(1+f r_i) over feasible f; binary shortcuts may not apply.','A wheel with several prize sizes needs more than win-versus-lose labels.'],[['A bet wins+1 unit with 40%, loses 1 with 20%, returns stake with 40%. Money EV per unit?','0.4−0.2=+0.2 units, or 20%.'],['Can you use q=60% as full-loss chance here?','No.40% is a zero-profit void, not a loss.'],['For these outcomes, what f maximizes expected log growth?','Solve 0.4/(1+f)−0.2/(1−f)=0; f=1/3≈33.33%.'],['What domain must be checked in a multi-outcome Kelly optimization?','Every possible wealth factor 1+fr_i must stay positive, plus external capital constraints.'],['If loss severity becomes−2 units, why must the feasible f range change?','The loss factor 1−2 f requires f<0.5 for finite log wealth.'],['Why can aggregating all winning outcomes into an average payout distort log growth?','Log is nonlinear; different payoff sizes cannot generally be replaced by their average inside it.']],'g(f)=Σp_i ln(1+f r_i)',[['(.4-.2)/(.4+.2)',1/3]]);
r(7,'decisions','portfolio-kelly','Portfolio log-growth optimization',['Choose all simultaneous exposures using their joint return outcomes.','It accounts for dependence and shared bankroll instead of separate optimal stakes.','Maximize E[ln(1+Σw_i r_i)] subject to feasible wealth and exposure constraints.','Several engines share one fuel tank; each cannot assume it owns the whole tank.'],[['Two positions each risk 15% on an identical full-loss event. Joint bankroll loss?','30%.'],['Why can adding individually optimal fractions be wrong?','The joint loss distribution and shared wealth change the growth optimum.'],['Would independent bet formulas handle a perfectly correlated event?','No. Marginal win chances do not encode the shared outcome.'],['What must a joint sizing model specify?','Joint probabilities, payoff distributions, transaction costs, capital limits and stress scenarios.'],['A common shock loses 30% on both halves of an equal-weight portfolio. Portfolio loss?','30%, not 15%.'],['Why are small-return mean/covariance Kelly approximations limited?','They may fail for large moves, skewed tails, leverage constraints or uncertain covariance estimates.']],'maximize E ln(1+wᵀr)',[['.5*(-.3)+.5*(-.3)',-.3]]);
r(7,'decisions','loss-constraint','Risk constraints versus growth optimum',['A tolerable loss or reserve rule can restrict an otherwise growth-optimal choice.','It incorporates obligations and survival into practical sizing.','Optimize within constraints; an unconstrained optimum is not automatically feasible.','The fastest route is irrelevant if the bridge cannot carry your vehicle.'],[['A model suggests€300 exposure but a valid risk limit allows€100. Feasible maximum?','€100, before any tighter operational constraints.'],['Does capping exposure prove all risk is controlled?','No. The loss model can be wrong, and several positions may share tail exposure.'],['A€1,000 account must keep€600 uncommitted. Maximum cash commitment?','€400, or 40% of account.'],['What should be stress-tested beside nominal exposure?','Actual loss under gaps, correlation, liquidity failure and funding needs.'],['Two trades each need€250 collateral but only€400 is free. Can both be opened unchanged?','No. Required€500 exceeds available€400.'],['Why distinguish commitment limits from expected-loss limits?','Collateral or cash tied up can be large even when expected loss is small; both can constrain action.']],'feasible action satisfies all capital constraints',[['1000-600',400]]);
r(7,'decisions','risk-budget','Allocation of risk budgets',['Divide tolerable risk across activities while accounting for shared losses.','It keeps attractive individual opportunities from creating excessive total exposure.','Use a joint risk measure and explicit limits; equal capital weights need not give equal risk.','Equal-size rooms can contain very different fire hazards.'],[['A 50/50 portfolio has asset SD s 10% and 30%. Equal capital means equal volatility exposure?','No. The second position contributes much more stand-alone volatility.'],['Why is summing each position’s 95% Va R not an exact portfolio 95% Va R?','Quantiles do not generally add; dependence and joint tails matter.'],['If four identical event exposures risk 5% each, combined full-loss risk?','20%.'],['What makes a useful risk budget review?','Include common drivers, current leverage, realistic stressed losses and changing correlations.'],['A business can lose€10,000 before missing payroll. Two projects may each lose€7,000 together. Concern?','The joint€14,000 loss exceeds the tolerance by€4,000, or 40%.'],['Why can risk parity based on historical covariance still fail?','Estimated covariance can change, and variance misses some asymmetric or liquidity risks.']],'joint loss constraints matter more than labels',[['(14000-10000)/10000*100',40]]);
r(7,'decisions','model-risk','Model risk in a decision',['Error from assumptions, structure or data that changes estimated decision value.','It distinguishes a well-computed answer from a trustworthy action.','Test alternatives, monitor calibration and compare results under plausible misspecification.','A perfect calculator cannot repair a map drawn for the wrong city.'],[['A strategy’s estimated EV is€3, but omitted average slippage is€5. Revised EV?','−€2.'],['Is a model reliable because it matches the data it was fitted on?','No. Flexible models can fit noise; use representative out-of-sample evaluation.'],['What differs between sampling error and structural model error?','Sampling error comes from limited random data; structural error comes from an incorrect model or missing mechanism.'],['What evidence helps uncover model failure?','Held-out performance, residual patterns, realistic execution, alternative specifications and changed environments.'],['A forecast assumes independence but ten trades share one earnings shock. Main flaw?','The joint downside is understated because the exposures are dependent.'],['Why keep a simpler benchmark model?','It reveals whether complexity adds repeatable value rather than only improving in-sample fit.']],'decision value is conditional on model validity',[['3-5',-2]]);
r(7,'applications','betting-sample','Win-rate uncertainty in betting',['Observed wins only estimate an underlying probability under a data model.','It prevents profitable-looking small samples from being treated as proven edges.','For independent Bernoulli trials, rough SE≈√(p̂(1−p̂)/n); use an appropriate interval for formal claims.','A small handful of coin flips can look strongly tilted by luck.'],[['Observed win rate 60% from 100 independent bets. Rough SE?','√(0.6×0.4/100)≈4.90 percentage points.'],['Does 60 wins in 100 prove true p exceeds 50%?','No. Assess an appropriate inferential method, selection, dependence and payoff price.'],['At the same observed rate,400 independent bets give what approximate SE?','2.45 percentage points, half the 100-bet SE.'],['Why can repeated bets on the same event overstate sample size?','Their outcomes are related; counting each as independent understates uncertainty.'],['At even-money odds, what expected ROI does p=55% imply?','10% before costs; uncertainty in p directly affects edge certainty.'],['Why must all predictions be timestamped before results?','It prevents hindsight selection and allows genuine out-of-sample evaluation.']],'SE(p̂)≈√(p̂(1−p̂)/n)',[['Math.sqrt(.6*.4/100)*100',Math.sqrt(24)]]);
r(7,'applications','poker-hourly','Poker hourly expectation',['Net expected earnings per hour, accounting for volume, costs and uncertainty.','It compares poker with other uses of time rather than a win-rate label alone.','Hourly profit≈net profit/representative hours; uncertainty and changing games matter.','A positive engine may still run too slowly to beat your next-best job.'],[['Observed net profit€600 in 200 hours. Hourly rate?','€3/hour.'],['Does a winning 2,000-hand sample establish the long-run hourly rate?','No. Poker variance, table selection and stake changes can make that sample highly uncertain.'],['At 5 big blinds/100 hands,€2 big blind and 80 hands/hour, modeled gross hourly profit?','5×€2×0.8=€8/hour before any costs not included in the rate.'],['What must be recorded to estimate sustainable hourly profit?','All sessions, stakes, hours, rake, promotions, expenses and game conditions.'],['A€5/hour estimate faces a feasible€12/hour alternative. Opportunity-cost gap?','€7/hour, before preference or flexibility differences.'],['Why can increasing stakes fail to multiply expected income proportionally?','Opponents, variance, bankroll needs and achievable edge change with the game.']],'hourly≈(bb/100)×€ per bb×hands/hour÷100',[['5*2*80/100',8]]);
r(7,'applications','backtest-bias','Backtest selection and missing failures',['Historical strategy results can be inflated by selective data or searched rules.','It separates repeatable trading evidence from an appealing historical story.','Include failed assets, past-available information, realistic costs and the full strategy search process.','Choosing only race winners after the finish makes any selection rule look skilled.'],[['A backtest includes only stocks that still trade today. What bias threatens it?','Survivorship bias: failed or delisted stocks are excluded.'],['Can using revised financial data simulate what a trader knew at the time?','Not necessarily. Later revisions may introduce look-ahead information.'],['Why does testing 1,000 rules increase the chance of a lucky winner?','Many noisy trials create extreme in-sample performance even without a real edge.'],['What should a genuine holdout remain free from?','Strategy design, parameter choice and repeated inspection that influences the model.'],['Gross historical profit€1,000 with realistic omitted costs€1,200 means what?','−€200 net.'],['A rule works only after many sample-window choices. What should be demanded?','Transparent search history, untouched validation and realistic execution, with selection-aware uncertainty.']],'net evidence requires out-of-sample, selection-aware checks',[['1000-1200',-200]]);
// Advanced: incompatible scales, constraints and sequential choices.
r(8,'arithmetic','dimensional-check','Dimensional checks',['Checking that units cancel to the units the answer claims.','It catches formulas that look numerical but combine incompatible quantities.','Write units beside each factor; money/time is not a probability or percentage.','A length added to a temperature is not a useful measurement.'],[['€10 per buyer times 100 buyers gives what unit and result?','€1,000. Buyer units cancel.'],['Why can €10/hour not be directly compared with 10% ROI?','They measure different things; include capital and time to make a common decision metric.'],['A rate of 0.02 conversions/visit multiplied by 5,000 visits gives what?','100 conversions.'],['What should happen if an EV expression adds euros to a probability?','Rebuild it; probabilities should weight money outcomes, not be added as money.'],['€2,000 capital earns€100 in five hours. ROI and profit/hour?','5% ROI and€20/hour; both help describe the opportunity.'],['Why can a correctly annualized percentage still fail a commercial comparison?','Required capital, labor, capacity and risk may differ; one number does not equal the whole opportunity.']],'units must match the claimed output',[['.02*5000',100]]);
r(8,'arithmetic','effective-exposure','Weighted exposure duration',['A money-and-time exposure measure when capital commitment changes.','It avoids treating unused or briefly used capital as invested all period.','State the exposure convention; capital-time is Σ capital×time, not simply a terminal balance.','Renting one room for a year differs from renting ten rooms for a day.'],[['€1,000 committed for 10 days and€2,000 for five days. Capital-days?','€20,000-days.'],['Is profit divided by ending capital always a comparable return?','No. Funding and exposure timing can distort it.'],['Over 15 days, what average committed capital does€20,000-days imply?','€20,000/15≈€1,333.33.'],['What denominator should be declared for an exposure-normalized return?','Starting capital, average exposure, peak commitment or stake turnover; they measure different things.'],['€200 profit over€20,000 capital-days gives what profit per€1,000-day?','€10 per€1,000-day.'],['Why can a high return on low average exposure still involve severe risk?','Peak exposure or a short stressed interval may create large loss despite a small time-average denominator.']],'average exposure=capital-time/total time',[['1000*10+2000*5',20000]]);
r(8,'arithmetic','margin-markup','Profit margin versus markup',['Margin divides profit by selling price; markup divides it by cost.','It avoids pricing mistakes and misleading business comparisons.','Margin=(price−cost)/price; markup=(price−cost)/cost.','The same€20 gap is a different share of an€80 cost and€100 sale.'],[['Cost€80, sale€100. Margin and markup?','20% margin and 25% markup.'],['Does 50% markup guarantee 50% margin?','No. Cost€100→price€150 gives 33.33% margin.'],['What price gives 25% margin on€60 cost?','€60/(1−0.25)=€80.'],['Which costs must a profit-margin calculation specify?','Gross cost versus all operating costs, refunds, taxes and allocation conventions.'],['A 20% markup on€50 cost yields what margin?','Price€60; margin€10/€60=16.67%.'],['Why can a higher gross margin coexist with lower net profit?','Lower volume or higher acquisition, support and fixed costs can outweigh the gross margin.']],'price=cost/(1−target margin)',[['60/(1-.25)',80]]);
r(8,'arithmetic','horizon-match','Matching return horizons',['Comparisons need rates and risks measured over consistent periods.','It stops daily, monthly and yearly numbers being combined as if identical.','Align the horizon and scaling assumptions before computing a ratio or expected payoff.','Compare runners over the same distance, not one’s sprint with another’s marathon.'],[['Daily excess mean 0.1%, daily SD 1%. Daily Sharpe?','0.1/1=0.1.'],['Can annual mean 10% be divided by daily SD 1% to report annual Sharpe 10?','No. The numerator and denominator use incompatible horizons.'],['Under independent stable returns, daily Sharpe 0.1 becomes what annualized value for 252 days?','0.1√252≈1.59, as an approximation.'],['What can undermine that annualization?','Serial dependence, changing variance, fat tails and incompatible return definitions.'],['A 30% total return over three years is what CAGR?','1.3^(1/3)−1≈9.14%.'],['Why disclose the sample length alongside annualized performance?','A short noisy record can produce an impressive annualized figure without strong evidence of persistence.']],'same horizon before ratio calculations',[['1.3**(1/3)-1',.09139288306110593]]);
r(8,'arithmetic','after-tax','After-tax comparison conventions',['Net amounts depend on which gains, costs and losses the tax rule recognizes.','It compares opportunities using consistent final cash outcomes.','Apply the stated hypothetical tax base and timing, and separate taxes from fees.','Two receipts with the same top-line amount can leave different spendable money.'],[['Under a hypothetical 20% tax on€100 profit after€10 deductible costs, net profit?','Tax=20%×€90=€18; net€72.'],['Why must you not use this hypothetical rate as a real tax rule?','Actual rules depend on jurisdiction, activity, timing and loss treatment; the exercise defines its own assumptions.'],['If the€10 cost is not deductible under the exercise, net profit?','€100−€20 tax−€10 cost=€70.'],['What makes two after-tax return figures comparable?','Same cash-flow timing, eligible deductions, loss assumptions and valuation basis.'],['Profit€200, hypothetical 25% tax and no other cost. Net profit?','€150.'],['Why can losses with limited tax offsets make upside/downside after-tax payoffs asymmetric?','Tax may reduce wins while providing a smaller or delayed benefit on losses. Model both outcomes explicitly.']],'net=profit−cost−tax on defined base',[['100-10-.2*90',72]]);
r(8,'decisions','robust-ev','Robust decisions across plausible models',['Compare actions over several defensible models rather than trusting one fitted world.','It tests whether a recommendation depends on fragile assumptions.','Report expected values and worst plausible cases under transparent model choices.','Try the key in several locks before assuming one copied key fits the building.'],[['Action A has EV€10 in one model and−€20 in another; B gives€2 in both. Robustness difference?','B is stable across these models; A’s preference depends on which model is credible.'],['Does a worst-case rule mean every imaginable disaster must dominate?','No. The uncertainty set needs justification; absurd unconstrained cases make the rule uninformative.'],['If both models give A more than B, what improves?','The ranking is less sensitive to that particular model uncertainty.'],['What should be checked about model weights or bounds?','They reflect evidence and realistic misspecification, not a convenient choice to force a result.'],['A model range gives ROI−3% to 8%; cost adds 2 percentage points. Net range?','−5%to6%.'],['Why retain scenario results instead of only averaging them?','An average can hide a damaging downside or a ranking reversal that matters for capital constraints.']],'stress rankings across justified models',[['-.03-.02',-.05]]);
r(8,'decisions','regret','Regret and minimax comparison',['Regret is the gap from the best action for a given state.','It offers an alternative way to compare actions when state probabilities are unreliable.','Compute state-wise best payoff minus chosen payoff; minimax regret minimizes the largest justified regret.','After seeing the weather, compare your chosen equipment with what would have been best.'],[['State 1: A 10,B 8; state 2:A−10,B 2. Maximum regret for each?','A:12; B:2. B minimizes maximum regret across these states.'],['Is minimizing regret the same as maximizing expected profit?','No. Expected profit needs probability weights; minimax regret uses a worst regret criterion.'],['What is regret for an action that is best in a state?','Zero.'],['What must be justified before using minimax regret?','The feasible actions, payoff table and set of states; preferences can favor another rule.'],['If A and B both pay€5 in all states, regret difference?','None; both have zero regret relative to the best available payoff.'],['Why can adding an unrealistic state distort a regret decision?','Its extreme payoff gap can dominate the maximum and change the recommendation without evidence.']],'regret(a,s)=best payoff(s)−payoff(a,s)',[['2-(-10)',12]]);
r(8,'decisions','discounted-choices','Present value under uncertainty',['Convert later cash outcomes to today’s value using a stated discount model.','It combines opportunity cost of time with uncertainty and cash-flow timing.','PV=Σ expected cash_t/(1+r)^t, when that risk/discount convention is justified.','Future euros are farther down the road; you need a conversion to compare them with euros now.'],[['Receive€110 in one year; discount rate 10%. Present value?','€110/1.1=€100.'],['Why should a risky payoff not be treated as guaranteed merely because it is discounted?','Discounting does not validate the probability or guarantee payment; risk assumptions must be explicit.'],['Receive€121 in two years at 10% yearly discount. PV?','€100.'],['What should be avoided when accounting for risk?','Charging the same risk twice through both reduced expected cash flows and an unjustified extra discount adjustment.'],['Project costs€90 now and pays expected€110 in one year at 10% discount. NPV?','€100−€90=€10.'],['Why can a positive NPV project still fail operationally?','Interim liquidity, execution constraints or incorrect cash-flow estimates may prevent realizing the modeled value.']],'NPV=Σ discounted expected cash−initial cost',[['121/1.1**2',100]]);
r(8,'decisions','liquidity','Liquidity constraints in decisions',['The ability to obtain usable cash when commitments must be paid.','It can make a profitable long-run project infeasible today.','Model the timing and stress of cash needs, not only terminal expected profit.','A full reservoir is useless for a fire if the pipe is blocked.'],[['A project yields€1,000 in a year but needs€500 next week; only€200 is liquid. Funding gap?','€300 next week.'],['Does positive total EV ensure bills can be paid on time?','No. The timing of cash inflows and outflows matters.'],['What differs between wealth and liquidity?','Wealth can be tied up in assets that cannot be sold quickly at a reasonable price.'],['What stress belongs in a liquidity plan?','Delayed receipts, margin calls, withdrawal limits and impaired sale prices occurring together.'],['Expected net profit€100 but financing the timing gap costs€120. Revised EV?','−€20.'],['Why can correlated good opportunities compete rather than simply add value?','They may require the same scarce cash at the same time, especially during stress.']],'cash balance_t must meet obligations_t',[['500-200',300]]);
r(8,'decisions','marginal-capital','Marginal use of scarce capital',['The additional value from assigning one more unit of a limited resource.','It prioritizes opportunities when money, capacity or time cannot fund everything.','Compare incremental net benefit per binding resource, with scale and risk limits.','The final available hour should go where it adds the most useful value.'],[['Project A needs€100 for EV€20; B needs€100 for EV€10. If only one is feasible, higher money EV?','A, under the same horizon and risk assumptions.'],['Why can average ROI fail to rank the next investment increment?','The marginal unit may have different returns, costs or capacity than past units.'],['A project earns€50 EV using ten hours; another€30 using three. EV/hour?','€5/hour versus€10/hour.'],['What resource must be identified before using a per-unit ranking?','The actual binding constraint: capital, labor, exposure or another scarce input.'],['Next€100 spend adds€8 revenue but€10 cost. Marginal net benefit?','−€2; more spending reduces value in this model.'],['Why can the highest ROI project fail to maximize total attainable profit?','It may be tiny or unscalable; evaluate feasible combinations, not ratios alone.']],'marginal value=incremental benefit−incremental cost',[['50/10',5],['30/3',10]]);
r(8,'applications','serial-sharpe','Autocorrelation and annualized Sharpe',['Returns across periods can covary, changing aggregate risk.','It challenges annualization shortcuts and smoothed performance claims.','Var(sum)=Σvariances+2Σpairwise covariances; use dependence-aware uncertainty.','Bumps occurring in clusters are harder than equally sized isolated bumps.'],[['Two equal-variance returns each have variance 1 and covariance 0.5. Sum variance?','1+1+2×0.5=3, not 2.'],['Why can positive serial correlation inflate a naive annualized Sharpe?','The independence shortcut can understate long-horizon risk and overstate the ratio.'],['If covariance is 0, what is sum variance here?','2.'],['What can create artificial serially smooth returns?','Stale pricing, infrequent marks, overlapping observations or discretionary valuation.'],['Variance 3 versus independence variance 2 differs by what percent?','50% higher variance; SD ratio√(3/2)≈1.225, about 22.47% higher.'],['Why use multiple performance diagnostics besides a corrected Sharpe?','Tail loss, drawdown, liquidity, leverage and selection bias still matter.']],'Var(ΣR)=ΣVar(R)+2ΣCov(R_i,R_j)',[['(3-2)/2*100',50]]);
r(8,'applications','calibrated-bets','Probability calibration versus betting value',['Calibration matches forecast frequencies with outcomes; value also depends on the price.','It separates a reliable chance estimate from a profitable market entry.','Compare forecasted probabilities with observed frequencies in representative samples, then evaluate net EV at available odds.','A good weather forecast can be accurate without making an overpriced umbrella a bargain.'],[['A calibrated 60% forecast is offered D=1.50. Expected ROI?','0.6×1.5−1=−10%, before costs.'],['Does accurate classification alone imply profitable bets?','No. Prices, probability quality and costs determine net return.'],['The same 60% chance at D=2.00 gives what modeled ROI?','+20%.'],['What should calibration checks include?','Enough data across probability ranges, all recorded forecasts, uncertainty and stable target definitions.'],['A model calls every game 50%, and half win. Does overall calibration prove useful discrimination?','No. It can be calibrated overall while failing to distinguish stronger and weaker cases.'],['Why monitor calibration after market or season changes?','The relationship learned from old data can shift, making earlier probabilities unreliable.']],'calibration plus price determines expected edge',[['.6*1.5-1',-.1]]);
r(8,'applications','parlays','Joint probability of combined bets',['A combined bet wins only if its required events occur together.','It reveals dependence and compounded pricing margins.','Multiply marginal probabilities only under independence; otherwise use conditional probabilities.','Several locks must open; knowing each lock’s chance does not tell you whether they share one key.'],[['Two independent 50% events both need to win. Jointchance?','25%.'],['Two perfectly identical 50% events: is their jointchance 25%?','No. It is 50%; the second occurs whenever the first does.'],['Three independent 60% events all succeed with what probability?','0.6³=21.6%.'],['What must be checked in a same-game combination?','Shared game factors, conditional relationships, settlement rules and offered payout.'],['Joint win chance 25%, combined D=3.50. Expected ROI?','0.25×3.5−1=−12.5%.'],['Why can attractive individual prices fail to produce a good combined price?','Dependence or combined-market margin can change the joint payoff value.']],'P(A∩B)=P(A)P(B|A)',[['.6**3*100',21.6]]);
r(8,'applications','time-information','Timestamped information in trading',['Use only information actually available before each historical decision.','It prevents future data or revised labels from leaking into a backtest.','Align release times, revisions, market access and execution lag with the decision timestamp.','A replay of yesterday’s race must hide tomorrow’s newspaper.'],[['A signal uses an earnings figure released after market close to trade at that day’s open. Valid?','No. The input was unavailable at the claimed entry time.'],['Can joining on a date alone guarantee no look-ahead?','No. Intraday release times, time zones and revisions matter.'],['Why are final index constituents risky for a past simulation?','They can reveal future inclusion or survival unavailable at the time.'],['What evidence should be retained for an information audit?','Original publication timestamps, historical snapshots, revision policy and order timing.'],['A quote appears at 12:00 but the model computes at 12:01. Can it assume the 12:00 fill?','Only with valid execution evidence; otherwise the simulated fill uses past unavailable access.'],['Why can a tiny lag destroy a high-frequency backtest edge?','The opportunity may disappear before the strategy can observe, calculate and execute.']],'features_available_time ≤ decision_time < execution_time');
// Very advanced: uncertainty large enough to change commercial decisions.
r(9,'arithmetic','threshold-rounding','Rounding near a decision threshold',['Displayed rounded numbers can conceal which side of a cutoff the exact calculation lies on.','It prevents narrow trading or business edges from being created by rounding.','Keep internal precision, compare exact quantities, then report sensible rounded outputs and uncertainty.','A blurred finish-line photo cannot decide a race won by millimeters.'],[['Estimated p = 33.32%, price D=3.00. Expected ROI before fees?','0.3332×3−1=−0.0004, or−0.04%.'],['If p is displayed 33.3%, can you infer it equals the 33.333…% threshold?','No. Rounding hides the relevant difference.'],['At p = 33.34%, D 3.00, expected ROI?','+0.02%, much smaller than common model and execution uncertainties.'],['What uncertainty matters more than decimal rounding here?','Probability estimation error, costs and whether the displayed price is executable.'],['A 0.02% edge on€1,000 has how much expected gross profit?','€0.20.'],['If a€0.20 edge has€1 minimum fees, how should the decision change?','Net EV is−€0.80 before other uncertainty; precise arithmetic exposes an unprofitable price.']],'ROI=p D−1 before actual costs',[['(.3332*3-1)*100',-.04]]);
r(9,'arithmetic','combined-stress','Combining adverse multiplicative changes',['Apply related shocks to their appropriate changing bases.','It estimates net outcomes when volume, price, costs or exchange rates move together.','Multiply factors for truly multiplicative components, then subtract separately modeled costs.','Several small cuts to different parts of a business can meet in one smaller final receipt.'],[['Sales volume falls 20%, net revenue per sale falls 10%. Total revenue change?','0.8×0.9−1=−28%.'],['Why not assume any two adverse percentages simply add?','They can act on different bases or interact; define the mechanism before calculating.'],['Foreign revenue rises 10% but currency value falls 10%. Home-currency revenue change?','1.1×0.9−1=−1%, before other factors.'],['What must be checked about stress scenarios?','Joint plausibility, dependence, timing and whether costs remain fixed or scale.'],['Revenue€1,000 falls 28%, while fixed costs stay€700. New profit?','€720−€700=€20, versus€300 before: a 93.33% profit fall.'],['Why can a modest revenue decline cause a huge profit decline?','Fixed costs absorb a much larger share of the remaining revenue.']],'revenue factor=volume factor×net price factor',[['(300-20)/300*100',280/3]]);
r(9,'arithmetic','conditional-aggregation','Aggregation across changing groups',['Overall rates combine subgroup rates and subgroup weights.','It identifies when an apparent performance improvement is only a mix shift.','Compare both within-group changes and changes in the group distribution.','Moving more visitors into the easy lane can raise the total success rate while both lanes worsen.'],[['Old:90% traffic at 10% conversion,10% at 50%. Overall?','0.9×10%+0.1×50%=14%.'],['New:10% traffic at 9% conversion,90% at 49%. Overall conversion?','45% exactly:0.1×9%+0.9×49%. Both subgroups worsened despite the overall rise.'],['What caused the aggregate rise in that example?','A large shift toward the subgroup with higher conversion.'],['What is needed before attributing an aggregate increase to a new feature?','Comparable populations or random assignment, subgroup effects and measurement consistency.'],['Using the old 90/10 weights with new 9%/49% rates gives what?','13%, revealing a one-percentage-point within-mix decline.'],['Which rate is the best summary for a decision?','The one matching the target population and causal question; show mix effects instead of picking a favorable aggregate.']],'overall rate=Σgroup weight×group rate',[['.1*.09+.9*.49',.45]]);
r(9,'arithmetic','absolute-stakes','Absolute scale behind relative effects',['A relative effect needs a baseline and population size to reveal its money or event impact.','It prices business or health-related changes without letting impressive ratios hide tiny amounts.','Absolute change=baseline×relative change; expected event change=absolute rate change×eligible count.','Doubling one drop differs from doubling a full reservoir.'],[['Conversion rises 5% relatively from 2%. New rate and absolute change?','2.1%;+0.1 percentage point.'],['Is “conversion up 5%” necessarily five extra buyers per 100 visits?','No. From 2%, it adds only 0.1 buyer per 100 visits in expectation.'],['At 10,000 visits, expected extra buyers from 2%→2.1%?','10buyers.'],['What commercial input is needed beyond extra buyers?','Net contribution per buyer, costs, refunds, retention and whether the effect is causal.'],['Those ten buyers each add€8 net contribution; rollout costs€100. Incremental profit?','€80−€100=−€20.'],['Why can a statistically precise relative lift be commercially unattractive?','Its absolute contribution may be smaller than deployment, support or opportunity costs.']],'incremental value=exposure×absolute lift×net unit value−cost',[['10000*(.021-.02)',10]]);
r(9,'arithmetic','uncertain-compounding','Uncertainty compounded over time',['Terminal wealth depends on the whole return distribution, not just a point forecast.','It separates a forecasted smooth growth line from plausible paths and tail losses.','Specify stochastic returns, dependence and cash flows; distinguish expected wealth from typical log growth.','A route’s average speed does not describe traffic jams or breakdowns.'],[['Two equally likely terminal outcomes€50 and€150. Mean terminal wealth?','€100.'],['Does mean€100 mean most outcomes will be close to€100?','No. In this example neither outcome equals the mean.'],['What is the geometric mean of the two terminal wealth values?','√(50×150)≈€86.60, a log-scale summary, not a guaranteed outcome.'],['What should be reported beside a projected average wealth curve?','Distribution or scenarios, drawdowns, model assumptions and cash-flow treatment.'],['If one modeled terminal outcome is zero with positive probability, expected log wealth?','−∞under that log-utility model.'],['Why can increasing investment horizon fail to eliminate risk?','Dependence, regime change, leverage, tail events and spending needs can remain or accumulate.']],'E[W] differs from exp(E[ln W])',[['Math.sqrt(50*150)',86.60254037844386]]);
r(9,'decisions','selected-edge','Selection-adjusted edge estimates',['The best of many noisy estimates is often too optimistic.','It prevents growth sizing from magnifying a winner chosen mainly by luck.','Account for the full search, shrink uncertain estimates and test on untouched representative data.','The loudest person in a noisy room may simply have had the loudest lucky echo.'],[['You search 1,000 strategies and choose the highest backtest EV. Is its raw EV an unbiased estimate of future EV?','Usually not. Selection tends to pick positive estimation noise.'],['Does adding more searched strategies strengthen evidence for the best one automatically?','No. It also increases opportunities to overfit.'],['Why may shrinkage reduce a chosen edge estimate?','It reflects uncertainty and selection rather than assuming the extreme estimate is entirely real.'],['What makes a test set no longer untouched?','Using its results to choose rules, filters or parameters, even indirectly.'],['An estimated 20% full Kelly fraction falls to 4% after validation. Difference?','80% lower fraction. This shows how inflated edge estimates can amplify exposure.'],['What should accompany a selected strategy before capital is expanded?','A reproducible search record, realistic execution, independent validation, uncertainty and risk limits.']],'best observed estimate ≠ best true edge',[['(20-4)/20*100',80]]);
r(9,'decisions','staged-investment','Staged commitment and informative pilots',['Commit resources in steps while learning whether scaling is valuable.','It can reduce downside and preserve expansion choices.','Compare pilot cost and information quality with lost speed, selection effects and full-scale payoffs.','Test one small bridge span before building the whole crossing.'],[['A€100 pilot creates€160 expected decision improvement. Net information value?','€60, if that improvement is genuinely incremental.'],['Does a successful tiny pilot guarantee the same result at large scale?','No. Audience mix, capacity, competition and costs may change.'],['What makes a pilot informative rather than merely cheap?','It measures the uncertainties that determine the scaling decision with representative data.'],['What must be planned before seeing the pilot outcome?','Success metrics, limits, continuation rules and a valid analysis, so hindsight does not dictate the story.'],['Pilot reveals failure and avoids an otherwise expected€500 loss, but costs€80. Net modeled saving?','€420 for that scenario; expected value must also average other pilot outcomes.'],['Why can always piloting be suboptimal?','Delay, measurement costs or expiring opportunities can exceed the value of what you learn.']],'stage value=option/information benefit−cost−delay',[['500-80',420]]);
r(9,'decisions','sunk-cost','Sunk costs and incremental decisions',['Past unrecoverable spending should not be added as a new cost of today’s choice.','It stops continuing bad projects merely to justify earlier losses.','Compare future incremental outcomes and feasible alternatives; past spending matters only through current constraints or information.','Money already spilled cannot be saved by spilling more.'],[['You spent€1,000; continuing now costs€200 for expected€150 revenue. Incremental EV?','−€50. The past€1,000 does not make the continuation worthwhile.'],['“We must continue to earn back the earlier cost.” What is wrong?','Recovery is not guaranteed; the next decision must stand on future benefits and costs.'],['If stopping releases equipment worth€100, what comparison must include it?','The€100 opportunity value of stopping or selling.'],['What past information can still be relevant?','What spending taught you, current asset value, contractual obligations and funding constraints.'],['Continue EV€80 versus stop value€100. Preferred by money EV?','Stop, by€20, under the stated model.'],['Why is a historical loss still relevant to risk capacity even though it is sunk?','It can reduce available bankroll and change which future risks are feasible.']],'choose by future incremental value',[['150-200',-50]]);
r(9,'decisions','stopping-rule','Optimal stopping versus statistical peeking',['A policy for when continuing an opportunity is worth more than stopping.','It compares future rewards and costs without abusing repeated significance tests.','Define state, continuation value, stopping payoff and information process; inferential error control is a separate issue.','You can decide when to leave a queue, but looking repeatedly at a noisy clock does not prove the queue is fast.'],[['Continuing offers expected€15 benefit and€20 additional cost. Stop or continue by incremental EV?','Stop; continuation EV is−€5.'],['Does a profit-based stopping rule make ordinary repeated p-value checks valid?','No. Sequential statistical testing requires a suitable design or adjustment.'],['What differs between a stopping payoff and continuation value?','Stopping realizes the current feasible value; continuation includes future uncertainty and costs.'],['Why must the rule depend on information available at the time?','A hindsight rule can use future outcomes and overstate attainable value.'],['Search for another offer costs€2 and raises expected best payoff by€1.5. Continue?','No by this one-step money EV model: net−€0.50.'],['Why can a multi-step search justify continuing even when the next offer looks weak?','Later options may add continuation value; evaluate the full feasible decision process.']],'continue if continuation value > stopping value',[['1.5-2',-.5]]);
r(9,'decisions','sensitivity-rank','Sensitivity of opportunity rankings',['Check how plausible input changes alter which action is preferred.','It focuses analysis on the few variables that can actually change the decision.','Find break-even values and ranking reversals, then prioritize evidence for sensitive inputs.','Measure the shaky leg that can topple the table, not every scratch on its surface.'],[['A has EV€120, B€100. A’s cost may rise by€30. Can the ranking reverse?','Yes. A could fall to€90, below B.'],['Should equally uncertain but irrelevant inputs get equal research effort?','No. Spend effort on uncertainties that can change action or risk.'],['What is the cost increase at which A and B tie here?','€20.'],['What makes a sensitivity range credible?','Evidence about actual input uncertainty, feasible combinations and dependencies.'],['Revenue€500 with variable costs€350 and fixed€100. Maximum extra cost before zero profit?','€50.'],['Why evaluate joint scenarios rather than changing only one input at a time?','Adverse inputs may move together; single-variable checks can miss a combined failure.']],'ranking threshold solves EV_A=EV_B',[['500-350-100',50]]);
r(9,'applications','sequence-risk','Sequence risk with withdrawals',['The order of returns matters when money is removed or exposure depends on the path.','It evaluates retirement, bankroll draws and funding obligations.','Model returns and cash flows in their actual order. Without flows, multiplication order alone does not change terminal wealth.','Taking water out between storms changes how much is left after the same weather.'],[['Start€100; returns+20%,−20%; withdraw€10 after each period. Final wealth?','(100×1.2−10)×0.8−10=€78.'],['Reverse those returns with the same withdrawals. Final wealth?','(100×0.8−10)×1.2−10=€74.'],['With no withdrawals, do those two orders give different endings?','No. Both end€96.'],['What cash-flow detail matters in sequence risk?','Timing, amount, necessity and whether withdrawals adjust after losses.'],['What is the€4 difference relative to the€74 ending?','About 5.41% more terminal wealth in the first order.'],['Why can a strategy with attractive CAGR still fail a spending plan?','Early losses and required withdrawals can deplete the base before recovery.']],'cash-flow timing makes return order matter',[['(100*1.2-10)*.8-10',78],['(100*.8-10)*1.2-10',74]]);
r(9,'applications','beta-vs-alpha','Market exposure versus independent skill',['Returns can come from common market risk rather than an independent predictive edge.','It evaluates whether a strategy adds value beyond a suitable benchmark.','Compare net performance with appropriate exposures and uncertainty; fitted alpha is not automatically causal skill.','Rising with the tide does not show that your boat has a stronger engine.'],[['A strategy earns 12% when a matching-risk benchmark earns 15%. Relative performance gap?','−3 percentage points; it earns 20% less return relative to 15%.'],['Does positive profit alone establish trading skill?','No. Market exposure, leverage and luck may explain it.'],['In a simple return model R=α+βR_market+error, what doesβdescribe?','Sensitivity to the modeled market return, under that specification.'],['What can make estimatedαmisleading?','Wrong benchmark, omitted risks, costs, overfitting, selection and short samples.'],['β=2, market return 5%, α=0 in a simplified one-period model. Predicted return?','10%, before costs and residual noise.'],['Why can a low historicalβfail in a crisis?','Nonlinear exposures, correlation changes and hidden tail risks may appear only under stress.']],'R=α+βR_market+residual',[['2*.05',.1]]);
r(9,'applications','capacity-impact','Capacity and market impact',['A strategy’s net edge can shrink as order size increases.','It limits scaling from small historical fills to large real positions.','Model size-dependent price impact, liquidity and fill probability rather than constant per-unit profit.','A narrow doorway works for one person but jams when a crowd arrives together.'],[['Gross edge€0.04/share, costs€0.01 at 100 shares. Net expected profit?','100×€0.03=€3.'],['At 1,000 shares costs rise to€0.05/share. Net expected profit?','1,000×(€0.04−€0.05)=−€10.'],['Why did ten times the size fail to give ten times the profit?','Per-unit execution cost changed with size and erased the edge.'],['What evidence supports a capacity claim?','Executable depth, order-level fills, stressed liquidity and competitor response, not just quoted top prices.'],['At what per-sharecost does a€0.04 gross edge break even?','€0.04/share, before any other costs.'],['Why might a profitable strategy be commercially small?','Limited liquidity, rare signals or impact can cap feasible net profit even with a real per-trade edge.']],'net profit(size)=size×[gross edge−cost(size)]',[['1000*(.04-.05)',-10]]);
// Professional quantitative reasoning: combine tools rather than trust a headline.
r(10,'arithmetic','leveraged-compound','Leveraged net growth over a path',['Compute actual equity factors after each move, costs and exposure changes.','It prevents averaging a leveraged return path into a misleading growth promise.','Apply the stated leverage and cost rule per period, check positive wealth and liquidation constraints, then compound.','A lever amplifies each hill and valley; the valleys change the next base.'],[['Two-period assets return+10%,−10%; daily-reset 2×exposure without costs. Equity total return?','1.2×0.8−1=−4%, compared with−1% unlevered.'],['Does twice exposure mean exactly twice the multi-period asset return?','No. Resetting leverage and compounding make the relationship path dependent.'],['Under a 2×resetmodel, a 50% asset loss has what idealized equity effect?','−100%, before costs; realistic liquidation rules can act earlier.'],['What must be audited before using the reset model?','Financing, rebalance timing, margin, market impact and extreme moves that violate assumed factors.'],['The +10%, −10%2×path also deducts 1% of post-return wealth each period. Net factor?','1.2×0.99×0.8×0.99=0.940896, a 5.9104% loss.'],['Why should a professional compare full wealth paths instead of one leverage multiple?','Drawdowns, funding and liquidation can determine feasibility before the terminal expected return matters.']],'For fees on post-return wealth: W_T=W_0Π[(1+L_t r_t)(1−fee_t)]',[['1.2*.99*.8*.99',.940896]]);
r(10,'arithmetic','multi-cost-hurdle','Exact multi-cost profitability hurdle',['Separate costs charged on invested amount, proceeds, holding time and profit.','It evaluates narrow opportunities without double-counting or omitting charges.','Write a full cash-flow equation, then solve for the unknown price or rate.','Each toll booth charges a different base; adding their signs blindly misprices the trip.'],[['Buy value€1,000; entry fee€5; holding cost€10; exit fee 1% of proceeds S. Break-even S?','0.99 S=€1,015; S≈€1,025.25, price growth≈2.525%.'],['Why is a 1.5% gross gain insufficient in this example?','It covers the fixed€15 but not the exit fee charged on sale proceeds.'],['At S=€1,030, net profit?','€1,030×0.99−€1,015=€4.70.'],['What input can dominate a small computed margin?','Adverse execution, timing uncertainty, financing changes or a mistaken fee base.'],['If expected gross proceeds€1,025 have±€20 uncertainty, is positive net profit established?','No. The point estimate is slightly below break-even and uncertainty is much larger than any narrow edge.'],['What makes a reviewable professional hurdle calculation?','Explicit entry and exit cash flows, units, timing, executable prices, assumptions and sensitivity around the threshold.']],'net = proceeds×(1−exit rate)−purchase−fixed costs',[['1030*.99-1015',4.7]]);
r(10,'arithmetic','tail-recovery','Tail loss and recovery feasibility',['A severe rare loss can dominate the capital required for recovery.','It compares strategies with similar ordinary returns but different catastrophic exposure.','Apply stress losses to wealth, calculate recovery hurdles and check whether funding survives.','A small average leak differs from one crack that drains almost the entire tank.'],[['Strategy A loses 20% in a stress; B loses 80%. Required recovery gains?','A:+25%; B:+400%.'],['Does a low estimated catastrophe probability make recovery capacity irrelevant?','No. The probability may be uncertain, and the loss can end the activity if it occurs.'],['If€10,000 falls 80%, what remains and what cash gap repairs it?','€2,000 remains;€8,000 is needed to regain€10,000.'],['What should be checked besides the probability-weighted loss?','Maximum feasible funding, concurrent obligations, correlations and how the loss estimate was obtained.'],['A 50% loss followed by three+20% periods leaves what fraction?','0.5×1.2³=0.864; still 13.6% below the initial value.'],['Why can “higher average return compensates for tail risk” be incomplete?','It ignores preferences, ruin, funding limits, uncertainty and the possibility that the average itself is misspecified.']],'recovery=d/(1−d), plus survival constraints',[['.5*1.2**3',.864]]);
r(10,'arithmetic','basket-method','Portfolio-weighting method audit',['Different weighting and rebalancing rules create different attainable returns.','It prevents selecting an index method that flatters an investment story.','Specify starting weights, rebalancing, costs, constituent availability and corporate actions.','A recipe can use equal spoonfuls or weight ingredients by their size; both give different meals.'],[['Two assets start equal; period 1 returns+100%,0%. Buy-and-holdweights afterward?','2/3 and 1/3, because values become 2 and 1.'],['Can an equal-weight historical average be treated as a free buy-and-hold return?','No. Maintaining equal weights requires rebalancing, executable trades and costs.'],['If period 2 returns−50%,0%, what is two-period buy-and-holdreturn?','Both assets return to initial values, so total 0%.'],['What must be checked in historical constituents?','Which assets existed and were selectable at each date, including failures and delistings.'],['Rebalance to 50/50 after period 1 in this example, ignoring costs. Two-period portfolio return?','Period 1+50%; period 2−25%;1.5×0.75−1=+12.5%.'],['Why can rebalancing gains in an example fail as a general trading claim?','They depend on future paths, costs and selection; one chosen path is not evidence of persistent edge.']],'attainable returns depend on weights and trading rules',[['1.5*.75-1',.125]]);
r(10,'arithmetic','cash-flow-return','Time-weighted versus money-weighted return',['Two return summaries answer different questions when external cash flows occur.','It separates manager-like performance from the investor’s actual cash timing experience.','Time-weighted return chains subperiod growth without flow effects; money-weighted return solves a cash-flow discount equation.','Judge the engine separately from when the driver added more fuel.'],[['An asset earns+50% then−50%, no external flow. Time-weightedtotal?','−25%:1.5×0.5−1.'],['Why can investor return differ when a large deposit comes before the loss?','More investor money is exposed during the bad period, changing the cash-weighted result.'],['Start€100, after+50% add€850, then lose 50%. Finalwealth?','(€150+€850)×0.5=€500; total contributions€950.'],['What does a valid money-weighted calculation require?','Every external cash-flow amount and date, terminal value, and a check for multiple or nonexistent IRR solutions.'],['Does terminal€500 minus€950 contributions fully describe an annual return?','No. It is a−€450 cash difference; a rate also needs timing.'],['Which return should a professional report?','Use the measure matching the question, often both: strategy growth independent of flows and the investor’s cash-flow experience.']],'TWR=Π(1+r_subperiod)−1; IRR solves discounted cash flows=0',[['(150+850)*.5',500]]);
r(10,'decisions','joint-uncertainty','Joint portfolio and model uncertainty',['Outcomes, parameters and liquidity may fail together across several opportunities.','It prevents a diversified-looking portfolio from concentrating one hidden assumption.','Stress both joint returns and shared estimation errors, then optimize within survival constraints.','Different ships can all depend on one port staying open.'],[['Five strategies each stake 4% on the same modeled edge. Jointfull-loss exposure?','20% if all stake losses occur together.'],['Does low measured return correlation prove their edge estimates are independently reliable?','No. They may share data, assumptions or selection methods.'],['What can happen if a common model feature is wrong?','Several expected edges can disappear simultaneously, even if past trade outcomes looked weakly correlated.'],['Which checks matter before scaling this portfolio?','Independent validation, shared drivers, stressed joint loss, execution capacity, financing and posterior uncertainty.'],['A 20% stress loss on€50,000 costs how much, and what gain repairs it?','€10,000 loss; remaining€40,000 needs+25%.'],['What is a stronger sizing recommendation than summing five single-strategy Kelly fractions?','A constrained joint exposure based on credible scenarios, uncertainty and survivable losses, with explicit assumptions and monitoring.']],'joint return and parameter uncertainty both matter',[['50000*.2',10000]]);
r(10,'decisions','optimizer-error','Optimization can amplify estimation error',['A mathematical optimizer exploits the inputs supplied, including their mistakes.','It explains why an elegant maximum can fail badly outside the fitted model.','Use uncertainty-aware estimation, constraints, benchmarks and untouched tests; inspect sensitivity of the chosen allocation.','A navigator perfectly follows a wrong map and confidently drives off course.'],[['A portfolio optimizer loads heavily on a tiny estimated edge with almost zero variance. What needs checking?','Stale pricing, insufficient data, numerical stability and whether those inputs are real and tradable.'],['Does convergence of the optimization algorithm validate its economic assumptions?','No. It only shows a solution to the specified calculation.'],['Why can regularization or simpler models improve realized results?','They can reduce sensitivity to noisy estimates, even if in-sample optimal value falls.'],['What should be reported with an optimized portfolio?','Inputs, uncertainty, constraints, validation, turnover and adverse scenarios, not only the maximum objective.'],['Estimated EV€100 versus benchmark€90; plausible error±€30. Is superiority secure?','No. The€10 gap is smaller than the plausible error.'],['Why should a professional reject “optimal” as a stand-alone endorsement?','Optimal always means under stated objectives, data and constraints; those can be wrong or incomplete.']],'optimized under a model ≠ validated in reality',[['100-90',10]]);
r(10,'decisions','growth-vs-money','Expected wealth versus sustainable growth',['Maximizing average terminal money and maximizing expected log wealth can recommend different exposures.','It chooses a goal that reflects survival, horizon and preferences.','Specify the objective before optimizing, and report distributions and constraints rather than only a mean.','A lottery can raise average prize money while making most paths disappointing.'],[['Evenmoneybet p = 60%: money EV rises linearly with stake. Why not stake 100% under log growth?','A 40% chance of zero wealth makes expected log wealth−∞; binary Kelly optimum is 20%.'],['Is expected log growth the correct objective for every decision-maker?','No. Objectives can include reserves, short-term needs, utility or mandated risk limits.'],['At 50% stake, what are the two wealth factors at even-money?','1.5 on a win and 0.5 on a loss.'],['What must be checked before recommending a growth-optimal policy?','Probability credibility, feasible horizon, reinvestment, dependence, preferences and survival constraints.'],['A+50%,−50% sequence gives what arithmetic mean and compound total?','Arithmeticmean 0%; compound total−25%.'],['Why report money EV, growth and tail outcomes together?','They reveal different aspects; an attractive mean can coexist with poor typical growth or unacceptable ruin risk.']],'different objectives produce different optima',[['1.5*.5-1',-.25]]);
r(10,'decisions','tail-decision','Decision value with rare catastrophic outcomes',['Include low-frequency severe outcomes when comparing opportunities.','It tests whether a small regular gain is worth a potentially activity-ending loss.','Estimate full payoff probabilities and their uncertainty, then enforce survival and utility constraints.','A road earning small tolls may still be a bad business if one collapse creates a huge bill.'],[['99% chance of +€10, 1% chance of −€1,000. EV?','0.99×€10−0.01×€1,000=−€0.10.'],['If catastrophe chance were 0.5%, would positive EV settle the choice?','No. EV becomes+€4.95, but loss tolerance, uncertainty and dependence still matter.'],['What probability of−€1,000 exactly offsets +€10 otherwise?','10/(1000+10)≈0.9901%.'],['What evidence is difficult for a rare-event estimate?','Representative tail observations, mechanism changes and common shocks; no observed catastrophe does not prove zero probability.'],['What is the EV at 2% catastrophe chance?','0.98×€10−0.02×€1,000=−€10.20.'],['Why should a professional use bounds or scenarios for poorly measured tails?','Tiny probability changes can reverse expected value, and one loss may exceed feasible capital.']],'EV=(1−p)G−p L, subject to survival',[['.99*10-.01*1000',-.1],['.98*10-.02*1000',-10.2]]);
r(10,'decisions','commercial-voi','Commercial value of further research',['Buy more evidence only when its expected effect on decisions exceeds its full cost.','It allocates research effort where it can change profitable action or prevent serious loss.','Compare optimized decision value with and without the evidence, accounting for errors, delay, cost and constraints.','A microscope is worth buying when it changes what you build, not just because it magnifies.'],[['Best current EV €1,000; a test raises expected chosen EV to €1,300; test €180 and delay €70. Net research value?','€50.'],['Why should a huge dataset not automatically be purchased?','It may not change the action, may be biased, or may cost more than its decision improvement.'],['Perfect information bound is €200, test plus delay cost €250. Purchase under that model?','No. Even perfect information cannot cover the full cost.'],['What makes the value estimate credible?','Representative signal quality, all signal outcomes, feasible resulting actions and sensitivity to model error.'],['A test reduces costly error chance 10%→6% on €5,000 loss exposure. Expected avoided loss?','4 percentage points×€5,000=€200.'],['What final recommendation should a complete quantitative analysis give?','A feasible action, key assumptions, expected incremental value, uncertainty, downside, alternatives and what new evidence would change it.']],'net research value = decision improvement−full research cost',[['1300-1000-180-70',50]]);
r(10,'applications','kelly-evidence','Kelly after edge validation',['Stake sizing follows credible edge evidence; it does not substitute for it.','It connects research quality, model calibration and correlated bankroll risk.','Validate prices and probabilities first, propagate uncertainty into joint sizing, then monitor real net outcomes.','Choosing the perfect fuel amount cannot make the wrong engine work.'],[['A 60% even-money estimate suggests 20% full Kelly; validation revises p to 52%. Newfull Kelly?','4%, an 80% reduction.'],['Would using 10% stake fromhalf the original estimate be conservative against the revised 4% optimum?','No.10% is still 2.5 times the revised full Kelly fraction.'],['At p = 52%, even-money expected ROI before costs?','4%.'],['What should happen if confidence in the edge weakens?','Reassess the model and feasible exposure; do not treat historic point estimates as fixed truths.'],['Four correlated 4% stakes may lose together. Joint stake loss?','16% of bankroll, before other exposures or worse-than-modeled losses.'],['What would justify increasing capital more strongly than a short winning streak?','Pre-recorded calibrated predictions, representative out-of-sample net returns, executable prices, capacity evidence and survivable joint risk.']],'evidence → probability/payoff model → constrained sizing',[['(20-4)/20*100',80]]);
r(10,'applications','search-and-holdout','Large backtest search and genuine holdouts',['A winning fit after extensive search needs evidence that did not influence the search.','It guards against strategy selection disguised as statistical certainty.','Record the full candidate search, costs and tuning; evaluate a frozen strategy on untouched data with dependence-aware uncertainty.','Trying 2,000 keysuntil one opens an old lock does not prove it opens the next lock.'],[['A strategy uses 2,000 searched parameters and reports one excellent backtest. First concern?','Overfitting and selection: the reported result may be a lucky extreme.'],['Does calling the last 20% of data a test set guarantee independence from design?','No. If it influenced strategy or parameter choices, it became part of selection.'],['What differs between nested validation and ordinary model selection on one holdout?','Nested validation separates tuning from outer evaluation, reducing optimism from reusing evaluation data.'],['Which financial realism checks remain after good statistical validation?','Past-available features, fills, slippage, fees, delistings, capacity and regime change.'],['Net edge appears only in one chosen window but vanishes in adjacent periods. What does that imply?','Fragile evidence; investigate selection, regime dependence and uncertainty before scaling.'],['What is a professional response to an impressive searched Sharpe?','Demand a reproducible search record, suitable benchmark, selection-aware inference and independent executable validation rather than one ratio.']],'search process belongs in the evidence audit');
r(10,'applications','roi-evidence','Interpreting a 400-bet 6% ROI record',['Observed profit is an estimate whose uncertainty depends on payouts, dependence and selection.','It separates a plausible sports edge from a short lucky record.','Use the actual net payoff distribution and pre-recorded representative samples; check intervals and calibration.','A positive score after one game is not the same as a proven stronger team.'],[['At even-money,400 equal bets win 53%. Observed ROI before costs?','2×0.53−1=6%.'],['Does 6% ROI from 400 bets prove a 6% future edge?','No. The estimate can be noisy and biased by selection or dependence.'],['Under independent Bernoulli assumptions, approximate SE of p̂ at 53% and n = 400?','√(0.53×0.47/400)≈2.50 percentage points. ROI standard error is twice that, about 4.99 points.'],['What can make that rough uncertainty calculation misleading?','Different odds, variable stakes, related outcomes, market changes, costs or selective recording.'],['Using a rough normal 95% interval,6% ROI ± 1.96 × 4.99 points spans what?','Approximately−3.78% to 15.78%; zero is included under those assumptions.'],['What evidence would make a commercial betting claim more convincing?','A larger untouched record, calibrated probabilities, realistic net prices, good benchmark comparison, selection-aware uncertainty and feasible capacity.']],'even-money ROI=2 p̂−1',[['Math.sqrt(.53*.47/400)*200',4.990991885387112]]);
r(10,'applications','integrated-commercial','Integrated quantitative opportunity audit',['Combine math, evidence, incentives and operational limits into one reviewable decision.','It prevents a correct isolated metric from approving a poor real-world opportunity.','Ask what is causal, what is net, what is uncertain, what can fail, and what the best feasible alternative earns.','Check the engine, road, fuel, destination and exit route before choosing the trip.'],[['An A/B test claims 5% relative conversion lift from 2%; 10,000 visits; €8 net per buyer; €100 rollout cost. Expected incremental profit?','Lift of 0.1 percentage point gives 10 buyers;10×€8−€100=−€20, assuming a genuine causal effect.'],['If p = 0.001, does that make this rollout profitable?','No. Statistical evidence does not change the negative modeled commercial payoff.'],['What if the true conversion lift were 0.2 percentage point?','20 extra buyers;€160−€100=€60 incremental profit.'],['Which few inputs most need checking here?','Causal absolute lift, eligible traffic, net unit contribution, deployment costs and whether the effect persists.'],['A competing feasible change has EV €40 and lower downside. Is the €60 point estimate automatically best?','No. Compare uncertainty, resource use, joint risks and opportunity cost before choosing.'],['A new strategy report combines high Sharpe, tiny p, 20% Kelly and positive ROI. What must you do before accepting it?','Audit data and search, correct inference, net payoffs, probability calibration, tails, joint exposure, executable capacity and alternatives. Metrics alone do not validate the decision.']],'incremental net value plus credible evidence and constraints',[['10000*.001*8-100',-20]]);
// Explicit prerequisite chains, plus cross-topic foundations where the arithmetic requires them.
const lastBySubject={};
const prerequisiteOrder=[...records.filter(r=>r.key==='prac-net-payoffs'),...records.filter(r=>r.key!=='prac-net-payoffs')];
for(const item of prerequisiteOrder){if(lastBySubject[item.subject])item.prerequisites=[lastBySubject[item.subject]];lastBySubject[item.subject]=item.key}
const extraPrerequisites={
 'prac-ev':['prac-percent-of','prob-chance','prac-net-payoffs'],
 'prac-risk-reward':['prac-ev','prac-net-payoffs','stat-mean'],
 'prac-decimal-odds':['prac-ratio','prob-chance'],
 'prac-pot-odds':['prac-percent-of','prob-chance'],
 'prac-kelly-purpose':['prac-break-even','prac-uncertain-probability'],
 'prac-kelly-formula':['prac-decimal-odds','prac-kelly-purpose'],
 'prac-log-growth':['prac-log-return','prac-compound-return'],
 'prac-portfolio-kelly':['prac-correlated-kelly','prac-diversification'],
 'prac-betting-sample':['stat-mean'],
 'prac-growth-vs-money':['prac-log-growth','prac-tail-recovery'],
 'prac-integrated-commercial':['prac-absolute-stakes','prac-commercial-voi']
};
for(const item of records)item.prerequisites=[...new Set([...item.prerequisites,...(extraPrerequisites[item.key]||[])])];
export default records;
